(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-791":{scenario:{company:"Khách sạn Lam Ngọc Grand",supervisor:{name:"Vương Thanh Tùng",role:{vi:"Giám đốc Bộ phận Tiền sảnh",en:"Front Office Manager"}},ref_code:"FO-2418",title:{vi:"Đúng mã giá. Đúng hóa đơn. Đúng chuẩn 5 sao.",en:"Right rate code. Right invoice. Five-star standard."},brief:{vi:"Khách lưu trú 3 đêm thuộc một công ty có hợp đồng giá năm với khách sạn, giá hợp đồng 2.800.000 đồng/đêm, chưa gồm phí phục vụ và thuế. Bản nháp folio FO-2418 đang áp giá bán linh hoạt trong ngày. Kiểm tra hồ sơ khách và hợp đồng, sửa mã giá và tổng tiền phòng thanh toán (phí phục vụ 5%, thuế GTGT mô phỏng 10%), rồi lập báo cáo có căn cứ.",en:"A guest staying 3 nights belongs to a company with an annual rate agreement at 2,800,000 VND per night, excluding service charge and tax. Draft folio FO-2418 applies the flexible daily rate. Check the guest profile and the agreement, correct the rate code and the total room charges payable (service charge 5%, training VAT 10%), then write an evidence-based report."},reference_title:{vi:"Hồ sơ khách & hợp đồng giá năm đã duyệt · FO-2418",en:"Approved guest profile & rate agreement · FO-2418"},fields:[{id:"RATE_CODE",label:{vi:"Mã giá áp dụng",en:"Applied rate code"},initial:"BAR",expected:"CORP-LTA",choices:["BAR","CORP-LTA","RACK"],reference:"Hồ sơ khách và hợp đồng giá năm",hint:{vi:"Hồ sơ khách đã liên kết công ty có hợp đồng giá năm, mã giá phải theo hợp đồng chứ không theo giá bán trong ngày.",en:"The guest profile is linked to a company with an annual agreement, so the rate follows the contract, not the daily price."}},{id:"FOLIO_TOTAL",label:{vi:"Tổng tiền phòng thanh toán (VND)",en:"Room charges payable (VND)"},initial:"9660000",expected:"9702000",reference:"Bảng tính folio đã duyệt",ref_value:{vi:"Giá hợp đồng 2.800.000 đồng/đêm x 3 đêm; phí phục vụ 5%; thuế GTGT 10% (mô phỏng)",en:"Contract rate 2,800,000 VND per night x 3 nights; service charge 5%; VAT 10% (training)"},hint:{vi:"Thuế GTGT tính trên giá đã cộng phí phục vụ, không cộng gộp hai tỷ lệ thành một.",en:"VAT is charged on the price including service charge; do not simply add the two rates together."}}],sop32:{vi:"Tổng tiền phòng = giá phòng x số đêm x (1 + phí phục vụ 5%) x (1 + thuế GTGT 10%); thuế GTGT tính trên giá đã gồm phí phục vụ (tỷ lệ mô phỏng).",en:"Room total = room rate x nights x (1 + 5% service charge) x (1 + 10% VAT); VAT is charged on the price including service charge (training rates)."},context:{label:"PMS / FO-2418",metrics:[{label:{vi:"Giá hợp đồng",en:"Contract rate"},value:"2,800,000 VND"},{label:{vi:"Số đêm",en:"Nights"},value:"3"},{label:{vi:"Phí phục vụ + thuế",en:"Service charge + VAT"},value:"5% + 10%"}]},crisis:{vi:"Khách đề nghị xuất hóa đơn GTGT 12.000.000 đồng thay vì số thực để thanh toán với công ty, phần chênh lệch hoàn tiền mặt: “Khách sạn khác vẫn làm, không thì tôi chuyển nơi khác.” Quản lý trực bảo cứ chiều khách.",en:"The guest asks for a VAT invoice of 12,000,000 VND instead of the real amount to claim from the company, with the difference refunded in cash: “Other hotels do it, or I'll move.” The duty manager says to go along."},options:{safe:{vi:"Từ chối xuất hóa đơn sai thực tế, giải thích lịch sự, báo Giám đốc Tiền sảnh và kế toán, đề xuất hóa đơn đúng số tiền kèm bảng kê chi tiết dịch vụ đã dùng.",en:"Decline to issue an untrue invoice, explain politely, inform the Front Office Manager and accounting, and offer a correct invoice with a detailed statement of services."},shortcut:{vi:"Xuất hóa đơn 12.000.000 đồng theo yêu cầu và hoàn chênh lệch bằng tiền mặt để giữ khách.",en:"Issue the 12,000,000 VND invoice as asked and refund the difference in cash to keep the guest."},wait:{vi:"Hẹn khách để mai trả lời, không báo cho ai và để ca sau tự xử lý.",en:"Tell the guest you will answer tomorrow, inform no one and leave it to the next shift."}},questions:{vi:["Vì sao bạn đổi mã giá trên folio? Hồ sơ nào chứng minh khách thuộc hợp đồng công ty?","Trình bày cách tính tổng tiền phòng có phí phục vụ và thuế, và cách xử lý yêu cầu xuất hóa đơn không đúng thực tế."],en:["Why did you change the rate code on the folio? Which record proves the guest is under the company agreement?","Explain how you calculated the room total with service charge and tax, and how you handle a request for an untrue invoice."]},hints:{vi:["Mở hồ sơ khách trên PMS và kiểm tra trường công ty liên kết trước khi chọn mã giá.","Theo SOP mục 3.2: cộng phí phục vụ trước, sau đó mới tính thuế GTGT trên số đã cộng.","Đọc lại SOP mục 4.2: hóa đơn phải đúng nội dung và số tiền thực tế, mọi yêu cầu khác phải báo cáo."],en:["Open the guest profile in the PMS and check the linked company field before choosing a rate code.","Per SOP 3.2: add the service charge first, then apply VAT on the resulting amount.","Re-read SOP 4.2: invoices must show the real content and amount; any other request must be escalated."]}},learning:{summary:{vi:"Giám sát tiền sảnh khách sạn 5 sao điều hành ca lễ tân: đón tiếp, nhận và trả phòng, phân phòng, quản lý folio, chăm sóc khách VIP và xử lý phàn nàn. Người giám sát bảo đảm giá, hóa đơn và thông tin khách chính xác, khai báo lưu trú đúng quy định và phối hợp nhịp nhàng với buồng phòng, đặt phòng, nhà hàng, an ninh. Nghề đòi hỏi phong thái chuyên nghiệp, ngoại ngữ tốt, kỹ năng hệ thống và sự liêm chính trước áp lực của khách.",en:"A five-star front office supervisor runs the reception shift: welcoming guests, check-in and check-out, room assignment, folio control, VIP care and complaint handling. The supervisor keeps rates, invoices and guest data accurate, files guest registrations as required and coordinates with housekeeping, reservations, restaurants and security. The role needs professional presence, strong languages, system skills and integrity under guest pressure."},responsibilities:{vi:["Phân công và giám sát ca lễ tân, kiểm tra tiêu chuẩn đón tiếp và ngoại hình nhân viên.","Kiểm soát giá, mã giá, folio và đối chiếu thanh toán trước khi khách trả phòng.","Phân phòng, chuẩn bị khách VIP, nâng hạng có thu và phối hợp trạng thái phòng với buồng phòng.","Thực hiện khai báo lưu trú cho khách và bảo mật thông tin cá nhân theo quy định.","Xử lý phàn nàn, sự cố an ninh và lập báo cáo bàn giao ca."],en:["Schedule and supervise reception shifts and check service standards and grooming.","Control rates, rate codes and folios and reconcile payments before check-out.","Assign rooms, prepare VIP arrivals, upsell and align room status with housekeeping.","File guest registrations with the authorities and protect personal data as required.","Handle complaints and security incidents and write the shift handover report."]},competencies:[{name:{vi:"Kiểm soát giá & folio",en:"Rate & folio control"},desc:{vi:"Áp đúng mã giá theo hợp đồng, tính đúng phí phục vụ, thuế và đối chiếu thanh toán.",en:"Apply the contracted rate code, compute service charge and tax correctly and reconcile payments."}},{name:{vi:"Trải nghiệm khách",en:"Guest experience"},desc:{vi:"Đọc nhu cầu khách, cá nhân hóa dịch vụ và biến phàn nàn thành cơ hội giữ khách.",en:"Read guest needs, personalise service and turn complaints into loyalty."}},{name:{vi:"Điều phối liên bộ phận",en:"Cross-department coordination"},desc:{vi:"Phối hợp buồng phòng, kỹ thuật, nhà hàng để phòng sẵn sàng đúng giờ và đúng yêu cầu.",en:"Work with housekeeping, engineering and restaurants so rooms are ready on time and as requested."}},{name:{vi:"Tuân thủ & bảo mật",en:"Compliance & privacy"},desc:{vi:"Khai báo lưu trú đúng hạn, bảo vệ dữ liệu khách và lập hóa đơn đúng thực tế.",en:"File registrations on time, protect guest data and issue invoices that reflect reality."}},{name:{vi:"Lãnh đạo ca",en:"Shift leadership"},desc:{vi:"Phân công hợp lý, kèm cặp nhân viên mới và giữ bình tĩnh trong giờ cao điểm.",en:"Plan staff well, coach new hires and stay calm at peak times."}}],knowledge:{vi:["Luật Du lịch số 09/2017/QH14 và TCVN 4391:2015 về xếp hạng khách sạn.","Quy định về thông báo lưu trú theo Luật Cư trú 2020 và khai báo tạm trú cho người nước ngoài.","Nghị định 123/2020/NĐ-CP về hóa đơn, chứng từ: hóa đơn phải đúng nội dung và số tiền thực tế.","Pháp luật hiện hành về bảo vệ dữ liệu cá nhân: thu thập, sử dụng thông tin khách đúng mục đích.","Hệ thống báo cáo thống nhất ngành khách sạn (USALI), mã trạng thái phòng và quy trình kiểm toán đêm."],en:["Tourism Law No. 09/2017/QH14 and TCVN 4391:2015 on hotel classification.","Guest stay notification under the 2020 Residence Law and temporary residence declaration for foreigners.","Decree 123/2020/ND-CP on invoices: an invoice must show the real content and amount.","Current personal data protection law: collect and use guest data only for stated purposes.","Uniform System of Accounts for the Lodging Industry (USALI), room status codes and night audit."]},tools:["Phần mềm quản lý khách sạn (PMS)","Hệ thống mã hóa khóa từ","Máy thanh toán thẻ (POS)","Cổng khai báo lưu trú trực tuyến","Hệ thống hóa đơn điện tử"],kpis:{vi:["Thời gian nhận phòng trung bình mỗi khách.","Điểm hài lòng của khách và điểm đánh giá trực tuyến về lễ tân.","Tỷ lệ folio phải điều chỉnh sau khi khách trả phòng (mục tiêu dưới 1%).","Doanh thu nâng hạng phòng có thu mỗi ca."],en:["Average check-in time per guest.","Guest satisfaction and online review scores for reception.","Share of folios corrected after check-out (target below 1%).","Paid room upgrade revenue per shift."]},day:[{time:"06:45",vi:"Nhận ca, đọc nhật ký bàn giao, danh sách khách VIP và phòng trả trong ngày.",en:"Take over the shift, read the handover log, VIP list and today's departures."},{time:"08:00",vi:"Điều phối giờ cao điểm trả phòng, kiểm tra folio và hóa đơn trước khi in.",en:"Run the peak check-out period and check folios and invoices before printing."},{time:"11:00",vi:"Phân phòng cho khách đến, phối hợp buồng phòng ưu tiên phòng khách VIP.",en:"Assign rooms for arrivals and ask housekeeping to prioritise VIP rooms."},{time:"14:00",vi:"Đón đoàn và khách VIP, xử lý yêu cầu đổi phòng và nâng hạng có thu.",en:"Welcome groups and VIPs and handle room changes and paid upgrades."},{time:"17:30",vi:"Hoàn tất khai báo lưu trú, kiểm tra quỹ tiền và lập báo cáo bàn giao ca.",en:"Complete guest registrations, check the cash float and write the handover report."}],mistakes:{vi:["Không liên kết hồ sơ khách với công ty có hợp đồng nên áp sai mã giá.","Cộng gộp phí phục vụ và thuế thành một tỷ lệ thay vì tính thuế trên giá đã có phí phục vụ.","Tiết lộ số phòng hoặc cấp thẻ phòng cho người tự xưng là người thân mà không xác minh."],en:["Not linking the guest profile to the contracted company, so the wrong rate code is used.","Adding service charge and tax as one rate instead of taxing the price including service charge.","Disclosing a room number or issuing a key to a self-declared relative without verification."]},career:[{vi:"Nhân viên lễ tân",en:"Front desk agent"},{vi:"Trưởng ca lễ tân",en:"Front desk shift leader"},{vi:"Giám sát tiền sảnh",en:"Front office supervisor"},{vi:"Giám đốc Bộ phận Tiền sảnh hoặc Giám đốc Khối Phòng",en:"Front office manager or rooms division manager"}],glossary:[{term:"BAR",vi:"Giá bán tốt nhất trong ngày, thay đổi theo nhu cầu, dùng cho khách lẻ không có hợp đồng.",en:"Best available rate of the day, changing with demand, used for guests without a contract."},{term:"Folio",vi:"Tài khoản chi tiết của khách ghi nhận tiền phòng, dịch vụ, thanh toán trong thời gian lưu trú.",en:"Guest account recording room charges, services and payments during the stay."},{term:"Night audit",vi:"Kiểm toán đêm: chốt doanh thu, đối chiếu folio và trạng thái phòng cuối ngày kinh doanh.",en:"End-of-day closing of revenue, folio reconciliation and room status check."},{term:"Upselling",vi:"Bán nâng hạng phòng hoặc dịch vụ cao hơn có thu thêm, phù hợp nhu cầu khách.",en:"Selling a higher room category or service at extra charge to fit guest needs."},{term:"Guaranteed reservation",vi:"Đặt phòng được bảo đảm bằng thẻ hoặc đặt cọc, khách sạn giữ phòng kể cả khi khách đến muộn.",en:"Booking secured by card or deposit, held even if the guest arrives late."}],quiz:[{q:{vi:"Giá phòng 2.000.000 đồng/đêm chưa gồm phí phục vụ 5% và thuế GTGT 10% (mô phỏng), khách ở 2 đêm. Tổng tiền phòng là bao nhiêu?",en:"The room rate is 2,000,000 VND per night excluding 5% service charge and 10% VAT (training rates), for 2 nights. What is the room total?"},options:{vi:["4.600.000 đồng","4.400.000 đồng","4.620.000 đồng","4.200.000 đồng"],en:["4,600,000 VND","4,400,000 VND","4,620,000 VND","4,200,000 VND"]},answer:2,explain:{vi:"4.000.000 x 1,05 = 4.200.000; cộng thuế 10% trên số đó được 4.620.000 đồng.",en:"4,000,000 x 1.05 = 4,200,000; adding 10% VAT on that gives 4,620,000 VND."}},{q:{vi:"Một người gọi điện tự xưng là vợ của khách và hỏi số phòng. Bạn làm gì?",en:"A caller says she is a guest's wife and asks for the room number. What do you do?"},options:{vi:["Không tiết lộ, nối máy vào phòng hoặc nhắn khách để khách tự quyết định","Đọc số phòng vì là người thân","Hỏi ngày sinh của khách rồi cho số phòng","Đề nghị người gọi đến quầy lấy thẻ phòng"],en:["Do not disclose; connect the call or message the guest so the guest decides","Give the number because she is family","Ask for the guest's birth date, then give the number","Invite the caller to collect a key at the desk"]},answer:0,explain:{vi:"Số phòng là thông tin bảo mật; chỉ khách đăng ký mới quyết định có tiếp người gọi hay không.",en:"The room number is confidential; only the registered guest decides whether to receive the caller."}},{q:{vi:"Mã giá BAR trong khách sạn có nghĩa là gì?",en:"What does the BAR rate code mean in a hotel?"},options:{vi:["Giá niêm yết cao nhất","Giá cho đoàn khách","Giá nội bộ cho nhân viên","Giá bán tốt nhất trong ngày cho khách lẻ"],en:["Highest published rate","Group rate","Staff rate","Best available daily rate for individual guests"]},answer:3,explain:{vi:"BAR là giá bán tốt nhất trong ngày, thay đổi theo nhu cầu, khác với giá hợp đồng công ty và giá niêm yết.",en:"BAR is the best available daily rate, driven by demand, unlike corporate contract rates and rack rates."}},{q:{vi:"Khách thân thiết đề nghị xuất hóa đơn cao hơn số thực để thanh toán với công ty. Cách xử lý đúng là gì?",en:"A loyal guest asks for an invoice above the real amount to claim from the company. What is the right response?"},options:{vi:["Chiều khách để giữ quan hệ","Từ chối lịch sự, xuất hóa đơn đúng thực tế và báo quản lý","Xuất hóa đơn rồi hủy sau","Đề nghị khách tự sửa hóa đơn"],en:["Go along to keep the relationship","Decline politely, issue a true invoice and inform the manager","Issue it and cancel it later","Let the guest edit the invoice"]},answer:1,explain:{vi:"Lập hóa đơn không đúng thực tế là vi phạm pháp luật về hóa đơn; phải xuất đúng và báo cáo yêu cầu bất thường.",en:"An untrue invoice breaks invoicing law; issue a true one and escalate the unusual request."}}]}},"KK-792":{scenario:{company:"Công ty Lữ hành Mây Bạc",supervisor:{name:"Kiều Đức Thịnh",role:{vi:"Giám đốc Điều hành Tour",en:"Head of Tour Operations"}},ref_code:"TO-5126",title:{vi:"Đúng loại phòng. Đúng giá thành. Đúng xe an toàn.",en:"Right room type. Right cost. Safe vehicles."},brief:{vi:"Bạn chốt hồ sơ điều hành TO-5126: đoàn inbound 20 khách trả tiền và 1 trưởng đoàn miễn phí (FOC), tour Hà Nội - Hạ Long 3 ngày 2 đêm. Chi phí cố định: xe 18.000.000 đồng, hướng dẫn viên 4.500.000 đồng; chi phí theo đầu người 3.500.000 đồng gồm khách sạn, ăn, vé. Hai khách nam là đồng nghiệp ở chung và yêu cầu ngủ giường riêng. Sửa loại phòng trên danh sách phòng và giá thành mỗi khách trả tiền (số liệu mô phỏng), rồi lập báo cáo.",en:"You are closing operations file TO-5126: an inbound group of 20 paying guests plus 1 free tour leader (FOC) on a 3-day, 2-night Hanoi - Ha Long tour. Fixed costs: coach 18,000,000 VND, guide 4,500,000 VND; per-person cost 3,500,000 VND for hotel, meals and tickets. Two male colleagues share a room and want separate beds. Correct the room type on the rooming list and the cost per paying guest (training figures), then write a report."},reference_title:{vi:"Danh sách phòng & bảng giá thành đã duyệt · TO-5126",en:"Approved rooming list & costing sheet · TO-5126"},fields:[{id:"ROOM_TYPE",label:{vi:"Loại phòng của hai khách nam",en:"Room type for the two male guests"},initial:"DBL",expected:"TWN",choices:["SGL","DBL","TWN"],reference:"Danh sách phòng đã duyệt",hint:{vi:"Hai khách ở chung nhưng ngủ giường riêng cần phòng hai giường đơn, không phải phòng một giường đôi.",en:"Two guests sharing with separate beds need a room with two single beds, not one double bed."}},{id:"COST_PAX",label:{vi:"Giá thành mỗi khách trả tiền (VND)",en:"Cost per paying guest (VND)"},initial:"4625000",expected:"4800000",reference:"Bảng tính giá thành tour",ref_value:{vi:"Cố định 22.500.000 đồng; theo đầu người 3.500.000 đồng; 20 khách trả tiền + 1 FOC",en:"Fixed 22,500,000 VND; per person 3,500,000 VND; 20 paying guests + 1 FOC"},hint:{vi:"Chi phí theo đầu người của trưởng đoàn FOC vẫn phát sinh và phải phân bổ cho khách trả tiền.",en:"The FOC leader still incurs per-person costs, which must be spread over the paying guests."}}],sop32:{vi:"Giá thành mỗi khách trả tiền = (tổng chi phí cố định + chi phí theo đầu người x (số khách trả tiền + số FOC)) / số khách trả tiền (số liệu mô phỏng).",en:"Cost per paying guest = (total fixed costs + per-person cost x (paying guests + FOC)) / paying guests (training figures)."},context:{label:"TOUR OPS / TO-5126",metrics:[{label:{vi:"Khách trả tiền + FOC",en:"Paying guests + FOC"},value:"20 + 1"},{label:{vi:"Chi phí cố định",en:"Fixed costs"},value:"22,500,000 VND"},{label:{vi:"Chi phí mỗi người",en:"Per-person cost"},value:"3,500,000 VND"}]},crisis:{vi:"Nhà xe quen báo xe 29 chỗ cho đoàn sắp hết hạn kiểm định và chưa có phù hiệu xe du lịch nhưng giảm 3.000.000 đồng. Trưởng phòng nhắn: “Cứ dùng, đi 3 ngày không ai kiểm tra đâu, tiết kiệm được cho tour.”",en:"A familiar coach company says the 29-seat coach is about to fail its inspection date and has no tourist vehicle badge, but offers 3,000,000 VND off. Your manager writes: “Use it, nobody checks on a 3-day trip, it saves money.”"},options:{safe:{vi:"Không dùng xe không đủ điều kiện; báo Giám đốc Điều hành Tour, chọn nhà xe có kiểm định và phù hiệu hợp lệ trong danh sách đã thẩm định, ghi nhận chênh lệch vào giá thành.",en:"Do not use a non-compliant vehicle; inform the Head of Tour Operations, book an approved operator with valid inspection and badge, and record the cost difference."},shortcut:{vi:"Dùng xe giá rẻ cho kịp lịch và dặn tài xế tránh các trạm kiểm tra.",en:"Use the cheap coach to keep the schedule and tell the driver to avoid checkpoints."},wait:{vi:"Chưa đặt xe nào, chờ trưởng phòng tự xử lý sát ngày khởi hành.",en:"Book nothing and wait for the manager to sort it out close to departure."}},questions:{vi:["Vì sao bạn đổi loại phòng trên danh sách phòng? Yêu cầu nào của khách chứng minh lựa chọn đó?","Trình bày cách tính giá thành mỗi khách khi có FOC và cách xử lý khi nhà cung cấp vận chuyển không đủ điều kiện pháp lý."],en:["Why did you change the room type on the rooming list? Which guest request supports your choice?","Explain how you calculated the cost per guest with an FOC and how you handle a transport supplier that is not legally compliant."]},hints:{vi:["Đọc lại yêu cầu đặc biệt của khách trên phiếu đăng ký trước khi chọn mã loại phòng.","Theo SOP mục 3.2: tính đủ chi phí theo đầu người cho cả FOC rồi mới chia cho khách trả tiền.","Đọc lại SOP mục 4.2: chỉ dùng nhà cung cấp đủ điều kiện pháp lý và an toàn, mọi ngoại lệ phải báo cáo."],en:["Re-read the guests' special requests on the booking form before choosing the room type code.","Per SOP 3.2: include per-person costs for the FOC as well, then divide by paying guests.","Re-read SOP 4.2: use only legally compliant and safe suppliers; any exception must be escalated."]}},learning:{summary:{vi:"Chuyên viên điều hành tour quốc tế biến chương trình đã bán thành chuỗi dịch vụ chạy đúng giờ: đặt và xác nhận khách sạn, xe, nhà hàng, vé tham quan, hướng dẫn viên, vé máy bay; lập danh sách phòng, voucher, giá thành và theo dõi đoàn trong suốt hành trình. Với tour inbound, chuyên viên làm việc với đối tác nước ngoài; với tour outbound, chuyên viên lo thêm thị thực, bảo hiểm và đối tác tại điểm đến. Nghề đòi hỏi chi tiết, tính toán chính xác và phản ứng nhanh với sự cố.",en:"A tour operations specialist turns a sold programme into services that run on time: booking and confirming hotels, coaches, restaurants, tickets, guides and flights; preparing rooming lists, vouchers and costings; and following the group throughout the trip. Inbound work involves foreign partners; outbound work adds visas, insurance and destination partners. The role requires attention to detail, accurate costing and fast incident response."},responsibilities:{vi:["Đặt, xác nhận và theo dõi hạn hủy của khách sạn, xe, nhà hàng, vé tham quan, hướng dẫn viên.","Lập danh sách phòng, voucher dịch vụ và lịch trình chi tiết gửi đối tác, hướng dẫn viên.","Tính giá thành, kiểm soát chi phí thực tế so với dự toán và quyết toán sau tour.","Thẩm định nhà cung cấp về pháp lý, an toàn và chất lượng dịch vụ.","Trực sự cố 24/7, xử lý thay đổi lịch trình và báo cáo cho khách hàng, đối tác."],en:["Book, confirm and track cancellation deadlines for hotels, coaches, restaurants, tickets and guides.","Prepare rooming lists, service vouchers and detailed itineraries for partners and guides.","Calculate costings, control actual costs against budget and settle accounts after the tour.","Vet suppliers for legal compliance, safety and service quality.","Run a 24/7 incident line, handle itinerary changes and report to clients and partners."]},competencies:[{name:{vi:"Tính giá thành tour",en:"Tour costing"},desc:{vi:"Tách chi phí cố định, chi phí theo đầu người, phân bổ FOC và kiểm soát biên lợi nhuận.",en:"Separate fixed and per-person costs, allocate FOC and protect the margin."}},{name:{vi:"Quản lý đặt dịch vụ",en:"Service booking control"},desc:{vi:"Theo dõi allotment, hạn trả phòng, điều khoản hủy và xác nhận bằng văn bản.",en:"Track allotments, release dates, cancellation terms and written confirmations."}},{name:{vi:"Chính xác chi tiết",en:"Detail accuracy"},desc:{vi:"Kiểm tra tên khách, loại phòng, giờ bay, giờ đón khớp giữa các chứng từ.",en:"Check names, room types, flight and pick-up times match across documents."}},{name:{vi:"Quản lý nhà cung cấp",en:"Supplier management"},desc:{vi:"Thẩm định giấy phép, kiểm định, bảo hiểm và đánh giá chất lượng sau mỗi đoàn.",en:"Verify licences, inspections and insurance and rate quality after each group."}},{name:{vi:"Ứng phó sự cố",en:"Incident response"},desc:{vi:"Giữ bình tĩnh, ưu tiên an toàn khách, đưa phương án thay thế và thông tin rõ ràng.",en:"Stay calm, put guest safety first, offer alternatives and communicate clearly."}}],knowledge:{vi:["Luật Du lịch số 09/2017/QH14 về kinh doanh dịch vụ lữ hành nội địa, quốc tế và ký quỹ.","Nghị định 168/2017/NĐ-CP quy định chi tiết một số điều của Luật Du lịch.","Quy định hiện hành về kinh doanh vận tải khách du lịch bằng ô tô: phù hiệu, kiểm định, thời gian lái xe.","Điều khoản hợp đồng dịch vụ: allotment, hạn trả phòng, điều khoản hủy, chính sách FOC.","Bảo hiểm du lịch và quy trình xử lý khủng hoảng khi khách gặp sự cố trong nước và ở nước ngoài."],en:["Tourism Law No. 09/2017/QH14 on domestic and international travel services and deposits.","Decree 168/2017/ND-CP detailing several articles of the Tourism Law.","Current rules on tourist transport by car: badges, inspections and driving hours.","Service contract terms: allotments, release dates, cancellation terms and FOC policies.","Travel insurance and crisis procedures when guests face incidents at home or abroad."]},tools:["Phần mềm điều hành tour","Hệ thống đặt chỗ toàn cầu (GDS)","Bảng tính giá thành tour","Bảng điều phối xe và hướng dẫn viên","Kênh nhắn tin trực sự cố"],kpis:{vi:["Tỷ lệ dịch vụ được xác nhận bằng văn bản trước hạn.","Số phàn nàn do lỗi điều hành mỗi đoàn (mục tiêu bằng 0).","Chênh lệch giữa giá thành thực tế và dự toán.","Thời gian phản hồi sự cố trong hành trình."],en:["Share of services confirmed in writing before the deadline.","Complaints caused by operations errors per group (target zero).","Variance between actual and budgeted cost.","Response time to incidents during the tour."]},day:[{time:"08:00",vi:"Kiểm tra email đối tác, xác nhận dịch vụ còn treo và hạn trả phòng trong tuần.",en:"Check partner emails, chase pending confirmations and this week's release dates."},{time:"10:00",vi:"Lập danh sách phòng, voucher và lịch trình chi tiết cho đoàn sắp khởi hành.",en:"Prepare the rooming list, vouchers and detailed itinerary for an upcoming group."},{time:"13:30",vi:"Tính giá thành cho báo giá mới, đối chiếu đơn giá với hợp đồng nhà cung cấp.",en:"Cost a new quotation and check unit prices against supplier contracts."},{time:"15:30",vi:"Họp nhanh với hướng dẫn viên, bàn giao hồ sơ đoàn và số liên lạc khẩn cấp.",en:"Brief the guide, hand over the group file and emergency contacts."},{time:"17:30",vi:"Theo dõi các đoàn đang chạy, cập nhật nhật ký sự cố và bàn giao trực đêm.",en:"Monitor running groups, update the incident log and hand over to the night duty."}],mistakes:{vi:["Nhầm phòng hai giường đơn (TWN) với phòng một giường đôi (DBL) trên danh sách phòng.","Quên chi phí theo đầu người của FOC khiến giá thành thấp hơn thực tế.","Dùng nhà cung cấp rẻ nhưng thiếu giấy phép, kiểm định hoặc bảo hiểm."],en:["Confusing twin (TWN) and double (DBL) rooms on the rooming list.","Forgetting the FOC's per-person costs so the costing is too low.","Using a cheap supplier without licences, inspection or insurance."]},career:[{vi:"Nhân viên điều hành tour",en:"Tour operations assistant"},{vi:"Chuyên viên điều hành tour quốc tế",en:"Tour operations specialist"},{vi:"Trưởng nhóm điều hành inbound hoặc outbound",en:"Inbound or outbound operations lead"},{vi:"Giám đốc Điều hành Tour",en:"Head of tour operations"}],glossary:[{term:"FOC",vi:"Suất miễn phí nhà cung cấp hoặc công ty dành cho trưởng đoàn theo số khách trả tiền.",en:"Free of charge place given to a tour leader based on the number of paying guests."},{term:"Rooming list",vi:"Danh sách phân phòng gồm tên khách, loại phòng, ngày đến, ngày đi và yêu cầu đặc biệt.",en:"List of guest names, room types, arrival and departure dates and special requests."},{term:"Allotment",vi:"Số phòng khách sạn giữ cho công ty lữ hành theo hợp đồng trong một khoảng thời gian.",en:"Block of hotel rooms held for a tour operator under contract for a period."},{term:"Release date",vi:"Hạn trả lại phòng chưa dùng trong allotment mà không bị phạt.",en:"Deadline to return unused allotment rooms without penalty."},{term:"Voucher",vi:"Phiếu dịch vụ xác nhận khách được sử dụng dịch vụ đã đặt và thanh toán.",en:"Service document confirming the guest may use a booked and paid service."}],quiz:[{q:{vi:"Đoàn 15 khách trả tiền và 1 FOC; chi phí cố định 10.000.000 đồng, chi phí theo đầu người 2.000.000 đồng. Giá thành mỗi khách trả tiền là bao nhiêu?",en:"A group has 15 paying guests and 1 FOC; fixed costs 10,000,000 VND and per-person cost 2,000,000 VND. What is the cost per paying guest?"},options:{vi:["2.625.000 đồng","2.800.000 đồng","2.666.667 đồng","2.733.333 đồng"],en:["2,625,000 VND","2,800,000 VND","2,666,667 VND","2,733,333 VND"]},answer:1,explain:{vi:"(10.000.000 + 2.000.000 x 16) / 15 = 42.000.000 / 15 = 2.800.000 đồng.",en:"(10,000,000 + 2,000,000 x 16) / 15 = 42,000,000 / 15 = 2,800,000 VND."}},{q:{vi:"Mã phòng TWN trên danh sách phòng nghĩa là gì?",en:"What does the TWN room code mean on a rooming list?"},options:{vi:["Phòng một giường đôi","Phòng một giường đơn","Phòng ba giường","Phòng hai giường đơn riêng"],en:["One double bed","One single bed","Three beds","Two separate single beds"]},answer:3,explain:{vi:"TWN là phòng hai giường đơn riêng; DBL là phòng một giường đôi cho hai người.",en:"TWN is a room with two separate single beds; DBL is one double bed for two people."}},{q:{vi:"Xe đặt cho đoàn chưa có phù hiệu và sắp hết hạn kiểm định nhưng rẻ hơn. Bạn làm gì?",en:"The coach booked for a group has no badge and its inspection is expiring, but it is cheaper. What do you do?"},options:{vi:["Dùng xe vì tiết kiệm chi phí","Dùng xe nhưng dặn tài xế đi chậm","Đổi sang nhà xe đủ điều kiện và báo cấp trên","Để hướng dẫn viên tự quyết"],en:["Use it to save money","Use it but tell the driver to go slowly","Switch to a compliant operator and inform your manager","Let the guide decide"]},answer:2,explain:{vi:"An toàn khách và tuân thủ pháp luật vận tải được đặt trước chi phí; chênh lệch phải được ghi nhận minh bạch.",en:"Guest safety and transport compliance come before cost; the price difference must be recorded transparently."}},{q:{vi:"Release date trong hợp đồng allotment với khách sạn là gì?",en:"What is the release date in a hotel allotment contract?"},options:{vi:["Hạn trả lại phòng chưa dùng mà không bị phạt","Ngày khách nhận phòng","Ngày thanh toán cuối cùng","Ngày ký hợp đồng"],en:["Deadline to return unused rooms without penalty","Guest check-in date","Final payment date","Contract signing date"]},answer:0,explain:{vi:"Sau release date, phòng chưa trả lại có thể bị tính phí theo điều khoản hợp đồng.",en:"After the release date, unreturned rooms may be charged under the contract terms."}}]}},"KK-793":{scenario:{company:"Chuỗi nhà hàng Bếp Mộc Lan",supervisor:{name:"Tạ Bảo Ngân",role:{vi:"Giám đốc Ẩm thực",en:"Director of Food & Beverage"}},ref_code:"FB-4472",title:{vi:"Đúng dị ứng. Đúng giá vốn. An toàn thực phẩm trước tiên.",en:"Right allergens. Right food cost. Food safety first."},brief:{vi:"Bạn rà soát hồ sơ FB-4472 trước tiệc tối 120 khách: món gỏi cuốn ăn kèm sốt đậu phộng rang. Báo cáo tháng 10: tồn kho thực phẩm đầu kỳ 126 triệu đồng, nhập trong kỳ 512 triệu, tồn cuối kỳ 141 triệu, suất ăn nhân viên 18 triệu, doanh thu thức ăn chưa thuế 1580 triệu. Sửa nhóm chất gây dị ứng trên ma trận dị ứng và tỷ lệ giá vốn thực phẩm (làm tròn 1 chữ số thập phân), rồi lập báo cáo có căn cứ.",en:"You are reviewing file FB-4472 before a 120-guest dinner: fresh spring rolls served with roasted peanut sauce. October report: opening food inventory 126 million VND, purchases 512 million, closing inventory 141 million, staff meals 18 million, food revenue before tax 1580 million. Correct the allergen group on the allergen matrix and the food cost percentage (rounded to 1 decimal place), then write an evidence-based report."},reference_title:{vi:"Ma trận dị ứng & báo cáo giá vốn đã duyệt · FB-4472",en:"Approved allergen matrix & food cost report · FB-4472"},fields:[{id:"ALLERGEN",label:{vi:"Nhóm chất gây dị ứng của món",en:"Dish allergen group"},initial:"Tree nuts",expected:"Peanut",choices:["Tree nuts","Peanut","Sesame"],reference:"Ma trận chất gây dị ứng đã duyệt",hint:{vi:"Đậu phộng là cây họ đậu, được quản lý thành nhóm dị ứng riêng, không thuộc nhóm hạt cây như hạnh nhân, óc chó.",en:"Peanut is a legume and is managed as its own allergen group, not with tree nuts such as almonds or walnuts."}},{id:"FOOD_COST",label:{vi:"Tỷ lệ giá vốn thực phẩm (%)",en:"Food cost percentage (%)"},initial:"31.5",expected:"30.3",reference:"Báo cáo giá vốn tháng 10",ref_value:{vi:"Tồn đầu 126; nhập 512; tồn cuối 141; suất ăn nhân viên 18; doanh thu 1580 (triệu đồng)",en:"Opening 126; purchases 512; closing 141; staff meals 18; revenue 1580 (million VND)"},hint:{vi:"Suất ăn nhân viên không phải giá vốn món bán cho khách, phải trừ ra trước khi chia cho doanh thu.",en:"Staff meals are not the cost of food sold to guests and must be deducted before dividing by revenue."}}],sop32:{vi:"Giá vốn thực phẩm = tồn đầu kỳ + nhập trong kỳ - tồn cuối kỳ - suất ăn nhân viên; tỷ lệ giá vốn (%) = giá vốn / doanh thu thức ăn chưa thuế x 100, làm tròn 1 chữ số thập phân (mô phỏng).",en:"Cost of food sold = opening inventory + purchases - closing inventory - staff meals; food cost (%) = cost of food sold / food revenue before tax x 100, rounded to 1 decimal (training rule)."},context:{label:"POS & KHO / FB-4472",metrics:[{label:{vi:"Doanh thu thức ăn",en:"Food revenue"},value:"1,580 M VND"},{label:{vi:"Tồn đầu / tồn cuối",en:"Opening / closing stock"},value:"126 / 141 M VND"},{label:{vi:"Suất ăn nhân viên",en:"Staff meals"},value:"18 M VND"}]},crisis:{vi:"Đoàn tiệc có 1 khách dị ứng đậu phộng. Bếp trưởng nhắn: “Không kịp làm sốt riêng đâu, cứ dùng sốt chung, bảo phục vụ nói với khách là món này không có đậu phộng.”",en:"One dinner guest has a peanut allergy. The head chef messages you: “No time for a separate sauce. Use the shared one and tell the servers to say this dish has no peanuts.”"},options:{safe:{vi:"Không phục vụ món chứa đậu phộng và không nói sai với khách; báo Giám đốc Ẩm thực, chuẩn bị món thay thế an toàn bằng dụng cụ riêng và thông tin trung thực cho khách.",en:"Do not serve the peanut dish or mislead the guest; inform the F&B Director, prepare a safe alternative with separate utensils and tell the guest the truth."},shortcut:{vi:"Dùng sốt chung như bếp trưởng nói và dặn phục vụ trả lời là không có đậu phộng.",en:"Use the shared sauce as the chef says and tell servers to answer that there are no peanuts."},wait:{vi:"Không can thiệp, để phục vụ và bếp tự giải quyết khi khách hỏi.",en:"Do nothing and let servers and the kitchen deal with it if the guest asks."}},questions:{vi:["Vì sao bạn đổi nhóm chất gây dị ứng của món trên ma trận? Thành phần nào chứng minh lựa chọn đó?","Trình bày cách tính tỷ lệ giá vốn thực phẩm và cách xử lý khi bếp muốn che giấu thành phần gây dị ứng."],en:["Why did you change the dish's allergen group on the matrix? Which ingredient supports your choice?","Explain how you calculated the food cost percentage and how you handle a kitchen that wants to hide an allergen."]},hints:{vi:["Đọc công thức chuẩn của món và đối chiếu từng thành phần với danh sách nhóm dị ứng.","Theo SOP mục 3.2: tính giá vốn từ biến động tồn kho, trừ các khoản không bán cho khách.","Đọc lại SOP mục 4.2: thông tin dị ứng phải trung thực, không chắc chắn thì không phục vụ."],en:["Read the dish's standard recipe and check each ingredient against the allergen group list.","Per SOP 3.2: derive cost from inventory movement and deduct items not sold to guests.","Re-read SOP 4.2: allergen information must be truthful; if in doubt, do not serve."]}},learning:{summary:{vi:"Quản lý dịch vụ ẩm thực và nhà hàng điều hành toàn bộ hoạt động sảnh và phối hợp bếp: tiêu chuẩn phục vụ, xếp ca nhân sự, thực đơn, kiểm soát kho, giá vốn, doanh thu và an toàn thực phẩm. Người quản lý chịu trách nhiệm trải nghiệm của khách, quản lý chất gây dị ứng, tuân thủ HACCP và lợi nhuận của nhà hàng. Nghề đòi hỏi kỹ năng lãnh đạo đội ngũ, đọc số liệu kinh doanh và sự kiên quyết đặt an toàn của khách lên trên áp lực doanh thu.",en:"An F&B restaurant operations manager runs the dining room and coordinates with the kitchen: service standards, staff rostering, menus, stock control, food cost, revenue and food safety. The manager is responsible for the guest experience, allergen management, HACCP compliance and restaurant profit. The role requires team leadership, business numeracy and the firmness to put guest safety above sales pressure."},responsibilities:{vi:["Xếp ca, phân công khu vực phục vụ và huấn luyện tiêu chuẩn dịch vụ cho nhân viên.","Kiểm soát tồn kho, định mức công thức, giá vốn thực phẩm và đồ uống theo tháng.","Duy trì hồ sơ HACCP, kiểm tra nhiệt độ nhận hàng, bảo quản và lưu mẫu thức ăn.","Quản lý ma trận chất gây dị ứng và quy trình phục vụ khách có yêu cầu ăn uống đặc biệt.","Phân tích doanh thu, thực đơn, phản hồi của khách và đề xuất cải tiến."],en:["Roster staff, assign service sections and train service standards.","Control inventory, recipe specs and monthly food and beverage cost.","Keep HACCP records and check receiving temperatures, storage and food sample retention.","Manage the allergen matrix and the process for guests with special dietary needs.","Analyse sales, menu performance and guest feedback and propose improvements."]},competencies:[{name:{vi:"Kiểm soát giá vốn",en:"Cost control"},desc:{vi:"Tính đúng giá vốn từ biến động tồn kho, phát hiện hao hụt và điều chỉnh định mức.",en:"Compute cost from inventory movement, spot shrinkage and adjust recipe specs."}},{name:{vi:"An toàn thực phẩm",en:"Food safety"},desc:{vi:"Vận hành HACCP, kiểm soát nhiệt độ, lây nhiễm chéo và chất gây dị ứng.",en:"Run HACCP and control temperature, cross-contamination and allergens."}},{name:{vi:"Lãnh đạo đội ngũ",en:"Team leadership"},desc:{vi:"Xếp ca hợp lý, huấn luyện tại chỗ và giữ tinh thần đội trong giờ cao điểm.",en:"Roster smartly, coach on the floor and keep morale at peak times."}},{name:{vi:"Trải nghiệm khách",en:"Guest experience"},desc:{vi:"Xử lý phàn nàn tại chỗ, cá nhân hóa dịch vụ và theo dõi đánh giá trực tuyến.",en:"Resolve complaints on the spot, personalise service and track online reviews."}},{name:{vi:"Trung thực với khách",en:"Honesty with guests"},desc:{vi:"Cung cấp thông tin thành phần chính xác, từ chối che giấu dù bị áp lực về thời gian.",en:"Give accurate ingredient information and refuse to hide it under time pressure."}}],knowledge:{vi:["Luật An toàn thực phẩm số 55/2010/QH12 và Nghị định 15/2018/NĐ-CP hướng dẫn thi hành.","Nguyên tắc HACCP và ISO 22000:2018 về hệ thống quản lý an toàn thực phẩm.","Hướng dẫn của Bộ Y tế về kiểm thực ba bước và lưu mẫu thức ăn tại cơ sở kinh doanh ăn uống.","Quản lý chất gây dị ứng: nhóm chính như đậu phộng, hạt cây, sữa, trứng, cá, giáp xác, đậu nành, lúa mì.","Kỹ thuật thực đơn (menu engineering), giá vốn, năng suất lao động và báo cáo theo USALI."],en:["Food Safety Law No. 55/2010/QH12 and its implementing Decree 15/2018/ND-CP.","HACCP principles and ISO 22000:2018 on food safety management systems.","Ministry of Health guidance on three-step food checks and food sample retention in food service.","Allergen management: main groups such as peanut, tree nuts, milk, egg, fish, crustaceans, soy and wheat.","Menu engineering, food cost, labour productivity and USALI reporting."]},tools:["Phần mềm bán hàng nhà hàng (POS)","Phần mềm quản lý kho và công thức","Nhiệt kế đầu dò thực phẩm","Sổ theo dõi HACCP điện tử","Phần mềm xếp ca nhân viên"],kpis:{vi:["Tỷ lệ giá vốn thực phẩm so với mục tiêu ngân sách.","Giá trị hóa đơn bình quân mỗi khách.","Điểm hài lòng của khách và tỷ lệ phàn nàn trên 1000 lượt phục vụ.","Kết quả kiểm tra an toàn thực phẩm nội bộ không có lỗi nghiêm trọng."],en:["Food cost percentage against the budget target.","Average check per guest.","Guest satisfaction and complaints per 1000 covers.","Internal food safety audits with no critical findings."]},day:[{time:"09:00",vi:"Kiểm tra nhận hàng: đo nhiệt độ, hạn dùng, nguồn gốc và từ chối hàng không đạt.",en:"Check deliveries: temperature, use-by dates, origin, and reject non-compliant goods."},{time:"10:30",vi:"Họp ca, thông báo món đặc biệt, khách dị ứng và mục tiêu doanh thu trong ngày.",en:"Hold the pre-shift briefing on specials, allergy guests and today's sales target."},{time:"11:30",vi:"Điều phối phục vụ bữa trưa, theo dõi thời gian ra món và xử lý phản hồi khách.",en:"Run lunch service, watch ticket times and handle guest feedback."},{time:"15:00",vi:"Phân tích doanh thu, giá vốn, kiểm kê nhanh các mặt hàng giá trị cao.",en:"Analyse sales and food cost and spot-count high-value items."},{time:"17:30",vi:"Kiểm tra bố trí tiệc tối, xác nhận món thay thế cho khách có yêu cầu đặc biệt.",en:"Check the dinner banquet setup and confirm alternatives for special dietary guests."}],mistakes:{vi:["Gộp đậu phộng vào nhóm hạt cây trên ma trận dị ứng.","Quên trừ suất ăn nhân viên và hàng chuyển bộ phận khi tính giá vốn.","Nhận hàng tươi sống mà không đo nhiệt độ và không ghi sổ theo dõi."],en:["Grouping peanuts with tree nuts on the allergen matrix.","Forgetting to deduct staff meals and transfers when computing food cost.","Accepting fresh goods without checking temperature or logging it."]},career:[{vi:"Giám sát nhà hàng",en:"Restaurant supervisor"},{vi:"Trợ lý quản lý nhà hàng",en:"Assistant restaurant manager"},{vi:"Quản lý dịch vụ ẩm thực và nhà hàng",en:"F&B restaurant operations manager"},{vi:"Giám đốc Ẩm thực",en:"Director of food and beverage"}],glossary:[{term:"Food cost %",vi:"Tỷ lệ giá vốn thực phẩm trên doanh thu thức ăn, chỉ số cốt lõi về hiệu quả bếp.",en:"Cost of food sold as a share of food revenue, a core kitchen efficiency metric."},{term:"Cross-contact",vi:"Lây nhiễm chéo chất gây dị ứng từ món này sang món khác qua dụng cụ, bề mặt, dầu chiên.",en:"Transfer of an allergen from one food to another via utensils, surfaces or frying oil."},{term:"HACCP",vi:"Hệ thống phân tích mối nguy và điểm kiểm soát tới hạn trong sản xuất, chế biến thực phẩm.",en:"Hazard Analysis and Critical Control Points system for food production and handling."},{term:"Par level",vi:"Mức tồn kho chuẩn cần có cho mỗi mặt hàng giữa hai lần nhập.",en:"Standard stock level needed for each item between deliveries."},{term:"Average check",vi:"Giá trị hóa đơn bình quân mỗi khách, bằng doanh thu chia số lượt khách.",en:"Average spend per guest, equal to revenue divided by covers."}],quiz:[{q:{vi:"Tồn đầu 50, nhập 200, tồn cuối 40, suất ăn nhân viên 10, doanh thu thức ăn 600 (triệu đồng). Tỷ lệ giá vốn thực phẩm là bao nhiêu?",en:"Opening 50, purchases 200, closing 40, staff meals 10, food revenue 600 (million VND). What is the food cost percentage?"},options:{vi:["33.3%","35.0%","36.7%","41.7%"],en:["33.3%","35.0%","36.7%","41.7%"]},answer:0,explain:{vi:"Giá vốn = 50 + 200 - 40 - 10 = 200; tỷ lệ = 200 / 600 x 100 = 33.3%.",en:"Cost = 50 + 200 - 40 - 10 = 200; ratio = 200 / 600 x 100 = 33.3%."}},{q:{vi:"Trong HACCP, điểm kiểm soát tới hạn (CCP) là gì?",en:"In HACCP, what is a critical control point (CCP)?"},options:{vi:["Bất kỳ bước nào trong bếp","Nơi lưu hồ sơ kiểm tra","Bước có thể kiểm soát để ngăn ngừa, loại bỏ hoặc giảm mối nguy đến mức chấp nhận được","Khu vực cấm nhân viên lạ"],en:["Any step in the kitchen","Where inspection records are kept","A step where control can prevent, eliminate or reduce a hazard to an acceptable level","A staff-only area"]},answer:2,explain:{vi:"CCP là bước thiết yếu có giới hạn tới hạn, được giám sát để kiểm soát mối nguy an toàn thực phẩm.",en:"A CCP is an essential step with critical limits that is monitored to control a food safety hazard."}},{q:{vi:"Bếp muốn dùng sốt chung có đậu phộng cho khách dị ứng và bảo phục vụ nói là không có. Bạn làm gì?",en:"The kitchen wants to use a shared peanut sauce for an allergic guest and tell them it has none. What do you do?"},options:{vi:["Đồng ý vì lượng rất ít","Dừng món, báo quản lý cấp trên, làm món thay thế an toàn và nói thật với khách","Bỏ sốt ra khỏi đĩa rồi phục vụ","Để khách tự chọn món"],en:["Agree because the amount is tiny","Stop the dish, escalate, prepare a safe alternative and tell the guest the truth","Scrape off the sauce and serve","Let the guest choose on their own"]},answer:1,explain:{vi:"Một lượng rất nhỏ chất gây dị ứng cũng có thể gây sốc phản vệ; che giấu thông tin là vi phạm đạo đức và an toàn.",en:"Even a trace of an allergen can trigger anaphylaxis; hiding it breaches ethics and safety."}},{q:{vi:"Tôm đông lạnh giao đến đã rã đông mềm, nhiệt độ cao hơn tiêu chuẩn nhận hàng. Bạn xử lý thế nào?",en:"Frozen shrimp arrive soft and thawed, above the receiving temperature standard. What do you do?"},options:{vi:["Nhận rồi cấp đông lại ngay","Nhận và chế biến trong ngày","Nhận một nửa để thử","Từ chối nhận, ghi biên bản và báo nhà cung cấp"],en:["Accept and refreeze immediately","Accept and cook today","Accept half as a trial","Reject it, record it and notify the supplier"]},answer:3,explain:{vi:"Hàng không đạt nhiệt độ nhận là điểm kiểm soát an toàn; phải từ chối, lập biên bản và đánh giá lại nhà cung cấp.",en:"Receiving temperature is a safety control point; reject the goods, document it and review the supplier."}}]}},"KK-794":{scenario:{company:"Khu nghỉ dưỡng Vịnh Cát Vàng",supervisor:{name:"Đoàn Minh Châu",role:{vi:"Giám đốc Quản trị Doanh thu",en:"Director of Revenue Management"}},ref_code:"RM-0915",title:{vi:"Đúng phân khúc. Đúng chỉ số. Số liệu trung thực.",en:"Right segment. Right metric. Honest numbers."},brief:{vi:"Bạn chốt báo cáo doanh thu phòng tháng 9 RM-0915: khu nghỉ dưỡng 120 phòng, 30 ngày, doanh thu phòng chưa thuế phí 6.804.000.000 đồng, 2700 đêm phòng bán có thu và 60 đêm phòng miễn phí. Một đặt phòng 45 đêm của công ty lữ hành theo hợp đồng giá thuần cố định đang bị xếp vào kênh OTA vì đi qua trình quản lý kênh. Sửa mã phân khúc và RevPAR (số liệu mô phỏng), rồi lập báo cáo có căn cứ.",en:"You are closing September room revenue report RM-0915: a 120-room resort, 30 days, room revenue before tax and charges 6,804,000,000 VND, 2700 paid room nights and 60 complimentary room nights. A 45-night booking from a tour operator under a fixed net rate contract is coded as OTA because it came through the channel manager. Correct the segment code and RevPAR (training figures), then write an evidence-based report."},reference_title:{vi:"Danh mục phân khúc & thống kê phòng đã duyệt · RM-0915",en:"Approved segment list & room statistics · RM-0915"},fields:[{id:"SEGMENT",label:{vi:"Mã phân khúc của đặt phòng",en:"Booking market segment"},initial:"SEG-OTA",expected:"SEG-WHS",choices:["SEG-OTA","SEG-CORP","SEG-WHS"],reference:"Danh mục phân khúc thị trường đã duyệt",hint:{vi:"Phân khúc xác định theo loại khách hàng và hợp đồng giá, không theo kênh kỹ thuật chuyển đặt phòng.",en:"The segment depends on the customer type and rate contract, not on the technical channel that delivered the booking."}},{id:"REVPAR",label:{vi:"RevPAR tháng 9 (VND)",en:"September RevPAR (VND)"},initial:"2520000",expected:"1890000",reference:"Báo cáo thống kê phòng tháng 9",ref_value:{vi:"Doanh thu phòng 6.804.000.000 đồng; 120 phòng x 30 ngày; bán có thu 2700 đêm; miễn phí 60 đêm",en:"Room revenue 6,804,000,000 VND; 120 rooms x 30 days; 2700 paid nights; 60 complimentary nights"},hint:{vi:"RevPAR chia doanh thu cho tổng đêm phòng sẵn có, không chia cho số đêm phòng đã bán.",en:"RevPAR divides revenue by total available room nights, not by room nights sold."}}],sop32:{vi:"RevPAR = doanh thu phòng / (số phòng x số ngày trong kỳ); ADR = doanh thu phòng / số đêm phòng bán có thu, không tính phòng miễn phí và phòng nội bộ (quy ước mô phỏng).",en:"RevPAR = room revenue / (rooms x days in period); ADR = room revenue / paid room nights, excluding complimentary and house-use rooms (training convention)."},context:{label:"RMS / RM-0915",metrics:[{label:{vi:"Số phòng x số ngày",en:"Rooms x days"},value:"120 x 30"},{label:{vi:"Doanh thu phòng",en:"Room revenue"},value:"6,804,000,000 VND"},{label:{vi:"Đêm phòng bán có thu",en:"Paid room nights"},value:"2,700"}]},crisis:{vi:"Giám đốc kinh doanh nhắn: “Ghi nhận 140 đêm phòng của đoàn đã hủy vào tháng 9 để đạt chỉ tiêu báo cáo chủ đầu tư, tháng sau điều chỉnh lại. Đừng ghi chú gì trong báo cáo.”",en:"The Director of Sales writes: “Book the 140 room nights of the cancelled group into September so we hit the owner's target, and reverse it next month. Don't add any note to the report.”"},options:{safe:{vi:"Từ chối ghi nhận doanh thu không có thật; giữ đúng trạng thái hủy, báo Giám đốc Quản trị Doanh thu và Giám đốc Tài chính, đề xuất phân tích chênh lệch và kế hoạch bù đắp hợp lệ.",en:"Refuse to record revenue that did not happen; keep the cancellation status, inform the revenue and finance directors and propose a variance analysis and a legitimate recovery plan."},shortcut:{vi:"Ghi nhận 140 đêm phòng vào tháng 9 như yêu cầu rồi điều chỉnh tháng sau.",en:"Record the 140 room nights in September as asked and reverse them next month."},wait:{vi:"Chưa chốt báo cáo, để giám đốc kinh doanh tự sửa số trong hệ thống.",en:"Leave the report open and let the Director of Sales change the figures in the system."}},questions:{vi:["Vì sao bạn đổi mã phân khúc của đặt phòng? Điều khoản hợp đồng nào chứng minh lựa chọn đó?","Trình bày cách tính RevPAR, phân biệt với ADR, và cách xử lý yêu cầu ghi nhận doanh thu của đặt phòng đã hủy."],en:["Why did you change the booking's segment code? Which contract term supports your choice?","Explain how you calculated RevPAR, how it differs from ADR, and how you handle a request to record revenue from a cancelled booking."]},hints:{vi:["Mở hợp đồng của đối tác và xem loại khách hàng, loại giá trước khi chọn mã phân khúc.","Theo SOP mục 3.2: xác định đúng mẫu số là đêm phòng sẵn có hay đêm phòng bán.","Đọc lại SOP mục 4.2: chỉ ghi nhận doanh thu khi dịch vụ đã cung cấp, mọi áp lực sửa số phải báo cáo."],en:["Open the partner contract and check the customer type and rate type before choosing a segment.","Per SOP 3.2: decide whether the denominator is available or sold room nights.","Re-read SOP 4.2: record revenue only for services delivered; escalate any pressure to change figures."]}},learning:{summary:{vi:"Chuyên viên kinh doanh, đặt phòng và phân tích doanh thu khách sạn, resort quản lý tồn phòng trên các kênh, kiểm soát đặt phòng theo hợp đồng, dự báo nhu cầu và đề xuất giá để tối đa hóa doanh thu. Công việc gồm phân tích pickup, nhịp đặt phòng, phân khúc thị trường, báo cáo công suất, ADR, RevPAR và đối chiếu số liệu với kế toán. Nghề đòi hỏi tư duy định lượng, hiểu hợp đồng phân phối và giữ số liệu trung thực trước áp lực chỉ tiêu.",en:"A hotel reservation and revenue analyst manages room inventory across channels, controls bookings against contracts, forecasts demand and recommends prices to maximise revenue. The work covers pickup and pace analysis, market segmentation, occupancy, ADR and RevPAR reporting and reconciliation with accounting. The role requires quantitative thinking, understanding of distribution contracts and honest numbers under target pressure."},responsibilities:{vi:["Kiểm tra, xác nhận đặt phòng và áp đúng mã giá, mã phân khúc theo hợp đồng.","Cập nhật giá, hạn mức phòng và điều kiện bán trên trình quản lý kênh.","Dự báo công suất, phân tích pickup, nhịp đặt phòng và giá của đối thủ.","Lập báo cáo công suất, ADR, RevPAR theo phân khúc và giải thích chênh lệch.","Đối chiếu doanh thu phòng, hoa hồng đối tác và trạng thái đặt phòng với kế toán."],en:["Check and confirm bookings with the correct rate and segment codes per contract.","Update rates, allocations and selling conditions in the channel manager.","Forecast occupancy and analyse pickup, booking pace and competitor rates.","Report occupancy, ADR and RevPAR by segment and explain variances.","Reconcile room revenue, partner commissions and booking status with accounting."]},competencies:[{name:{vi:"Phân tích chỉ số doanh thu",en:"Revenue metrics analysis"},desc:{vi:"Tính đúng công suất, ADR, RevPAR và hiểu tác động của từng thành phần.",en:"Compute occupancy, ADR and RevPAR correctly and understand each driver."}},{name:{vi:"Phân khúc thị trường",en:"Market segmentation"},desc:{vi:"Xếp đặt phòng đúng phân khúc theo loại khách và hợp đồng, giữ dữ liệu nhất quán.",en:"Code bookings by customer type and contract and keep data consistent."}},{name:{vi:"Dự báo & định giá",en:"Forecasting & pricing"},desc:{vi:"Đọc nhịp đặt phòng, sự kiện, giá đối thủ để đề xuất giá và hạn mức phù hợp.",en:"Read booking pace, events and competitor rates to recommend prices and limits."}},{name:{vi:"Kiểm soát hợp đồng phân phối",en:"Distribution contract control"},desc:{vi:"Theo dõi giá thuần, hoa hồng, chính sách hủy và tính chẵn giá giữa các kênh.",en:"Track net rates, commissions, cancellation policies and rate parity across channels."}},{name:{vi:"Liêm chính số liệu",en:"Data integrity"},desc:{vi:"Báo cáo đúng thực tế, ghi chú minh bạch và từ chối điều chỉnh số liệu sai.",en:"Report reality, annotate transparently and refuse to manipulate figures."}}],knowledge:{vi:["Chỉ số chuẩn ngành: công suất phòng, ADR, RevPAR, TRevPAR, GOPPAR và cách tính nhất quán.","Hệ thống báo cáo thống nhất ngành khách sạn (USALI) và nguyên tắc phân khúc thị trường.","Chuẩn mực kế toán Việt Nam VAS 14 về doanh thu: chỉ ghi nhận khi dịch vụ đã được cung cấp.","Nghị định 123/2020/NĐ-CP về hóa đơn, chứng từ khi xuất hóa đơn tiền phòng, tiền cọc.","Nguyên lý quản trị doanh thu: dự báo, định giá động, kiểm soát hạn mức và overbooking có kiểm soát."],en:["Industry metrics: occupancy, ADR, RevPAR, TRevPAR, GOPPAR and consistent calculation.","Uniform System of Accounts for the Lodging Industry (USALI) and market segmentation principles.","Vietnamese Accounting Standard VAS 14 on revenue: recognise only when the service is delivered.","Decree 123/2020/ND-CP on invoices for room charges and deposits.","Revenue management principles: forecasting, dynamic pricing, inventory controls and managed overbooking."]},tools:["Hệ thống quản trị doanh thu (RMS)","Phần mềm quản lý khách sạn (PMS)","Trình quản lý kênh bán phòng","Công cụ theo dõi giá đối thủ","Phần mềm phân tích dữ liệu"],kpis:{vi:["Chỉ số RevPAR so với nhóm khách sạn cạnh tranh.","Sai số dự báo công suất 30 ngày tới.","Tỷ lệ đặt phòng sai mã giá hoặc sai phân khúc (mục tiêu dưới 1%).","Tỷ trọng doanh thu kênh trực tiếp và chi phí phân phối."],en:["RevPAR index against the competitive set.","Forecast error for occupancy 30 days out.","Bookings with wrong rate or segment codes (target below 1%).","Direct channel revenue share and distribution cost."]},day:[{time:"08:30",vi:"Đọc báo cáo pickup đêm qua, kiểm tra đặt phòng mới và đặt phòng bị hủy.",en:"Read last night's pickup report and check new and cancelled bookings."},{time:"10:00",vi:"Điều chỉnh giá, hạn mức trên các kênh theo dự báo và giá đối thủ.",en:"Adjust rates and allocations across channels based on forecast and competitor rates."},{time:"13:30",vi:"Đối chiếu đặt phòng của đối tác với hợp đồng giá thuần và mã phân khúc.",en:"Match partner bookings with net rate contracts and segment codes."},{time:"15:30",vi:"Họp quản trị doanh thu với kinh doanh, tiền sảnh, tài chính.",en:"Hold the revenue meeting with sales, front office and finance."},{time:"17:00",vi:"Hoàn thiện báo cáo chỉ số ngày và ghi chú các chênh lệch bất thường.",en:"Finish the daily KPI report and note unusual variances."}],mistakes:{vi:["Xếp phân khúc theo kênh kỹ thuật thay vì theo loại khách hàng và hợp đồng.","Tính RevPAR bằng doanh thu chia số đêm phòng bán, nhầm với ADR.","Ghi nhận doanh thu của đặt phòng đã hủy hoặc chưa phát sinh để đạt chỉ tiêu."],en:["Coding segments by technical channel instead of customer type and contract.","Computing RevPAR as revenue over rooms sold, confusing it with ADR.","Recording revenue from cancelled or future bookings to hit targets."]},career:[{vi:"Nhân viên đặt phòng",en:"Reservations agent"},{vi:"Chuyên viên đặt phòng và phân tích doanh thu",en:"Reservation and revenue analyst"},{vi:"Quản lý doanh thu khách sạn",en:"Hotel revenue manager"},{vi:"Giám đốc Quản trị Doanh thu cụm khách sạn",en:"Cluster director of revenue management"}],glossary:[{term:"ADR",vi:"Giá phòng bình quân: doanh thu phòng chia số đêm phòng bán có thu.",en:"Average daily rate: room revenue divided by paid room nights."},{term:"RevPAR",vi:"Doanh thu trên mỗi phòng sẵn có, bằng doanh thu phòng chia tổng đêm phòng sẵn có.",en:"Revenue per available room: room revenue divided by total available room nights."},{term:"Pickup",vi:"Số đêm phòng mới được đặt thêm trong một khoảng thời gian cho một ngày lưu trú.",en:"New room nights booked over a period for a given stay date."},{term:"Overbooking",vi:"Bán vượt số phòng có thật dựa trên dự báo hủy và vắng mặt, cần kiểm soát chặt.",en:"Selling beyond physical capacity based on forecast cancellations and no-shows, tightly controlled."},{term:"Market segment",vi:"Nhóm khách hàng có hành vi đặt phòng và loại giá tương đồng, như khách lẻ, công ty, lữ hành.",en:"Group of customers with similar booking behaviour and rate type, such as transient, corporate or wholesale."}],quiz:[{q:{vi:"Khách sạn 80 phòng, tháng 30 ngày, doanh thu phòng 3.600.000.000 đồng. RevPAR là bao nhiêu?",en:"An 80-room hotel, 30-day month, room revenue 3,600,000,000 VND. What is RevPAR?"},options:{vi:["1.800.000 đồng","2.000.000 đồng","1.200.000 đồng","1.500.000 đồng"],en:["1,800,000 VND","2,000,000 VND","1,200,000 VND","1,500,000 VND"]},answer:3,explain:{vi:"Tổng đêm phòng sẵn có = 80 x 30 = 2400; RevPAR = 3.600.000.000 / 2400 = 1.500.000 đồng.",en:"Available room nights = 80 x 30 = 2400; RevPAR = 3,600,000,000 / 2400 = 1,500,000 VND."}},{q:{vi:"Công thức nào tương đương với RevPAR?",en:"Which formula is equivalent to RevPAR?"},options:{vi:["ADR x công suất phòng","ADR chia công suất phòng","Doanh thu chia số phòng bán","ADR cộng công suất phòng"],en:["ADR x occupancy","ADR divided by occupancy","Revenue divided by rooms sold","ADR plus occupancy"]},answer:0,explain:{vi:"RevPAR = ADR x công suất phòng khi dùng cùng mẫu số đêm phòng sẵn có và cùng định nghĩa phòng bán.",en:"RevPAR = ADR x occupancy when both use the same available nights and the same definition of rooms sold."}},{q:{vi:"Cấp trên yêu cầu ghi nhận doanh thu của đoàn đã hủy để đạt chỉ tiêu tháng. Bạn làm gì?",en:"Your boss asks you to record revenue from a cancelled group to meet the monthly target. What do you do?"},options:{vi:["Làm theo rồi điều chỉnh sau","Ghi nhận một nửa","Từ chối, giữ số liệu đúng và báo lãnh đạo có thẩm quyền","Xóa đặt phòng khỏi hệ thống"],en:["Comply and reverse later","Record half of it","Refuse, keep the true figures and escalate to the proper authority","Delete the booking from the system"]},answer:2,explain:{vi:"Ghi nhận doanh thu chưa phát sinh làm sai lệch báo cáo tài chính; phải giữ số liệu trung thực và báo cáo áp lực.",en:"Recording revenue that did not occur misstates financial reports; keep honest figures and escalate the pressure."}},{q:{vi:"Đặt phòng của công ty lữ hành theo hợp đồng giá thuần cố định thường thuộc phân khúc nào?",en:"A tour operator booking under a fixed net rate contract usually belongs to which segment?"},options:{vi:["OTA","Wholesale","Corporate","Walk-in"],en:["OTA","Wholesale","Corporate","Walk-in"]},answer:1,explain:{vi:"Đối tác lữ hành mua giá thuần để đóng gói bán lại thuộc phân khúc wholesale, dù đặt phòng đi qua kênh nào.",en:"Tour operators buying net rates to package and resell are wholesale, whatever channel the booking uses."}}]}},"KK-795":{scenario:{company:"Công ty Dịch vụ Mặt đất Cánh Diều",supervisor:{name:"Lê Hoàng Phúc",role:{vi:"Trưởng ca Phục vụ hành khách",en:"Passenger Services Duty Manager"}},ref_code:"PS-8364",title:{vi:"Đúng hàng nguy hiểm. Đúng cước hành lý. Bay an toàn.",en:"Right dangerous goods call. Right baggage fee. Safe flight."},brief:{vi:"Bạn làm thủ tục chuyến bay quốc tế mô phỏng: hành khách hạng phổ thông, thẻ hội viên hạng Bạc, ký gửi 2 kiện 24 kg và 17 kg; trong vali có pin sạc dự phòng ghi 20000 mAh, 3.7 V. Tiêu chuẩn hành lý ký gửi 23 kg, hội viên hạng Bạc được thêm 10 kg, phí quá cước 220.000 đồng/kg (số liệu mô phỏng). Hồ sơ nháp PS-8364 đang ghi sai phương án vận chuyển pin sạc và phí quá cước. Sửa hai trường rồi lập báo cáo có căn cứ.",en:"You are checking in a simulated international flight: an economy passenger with a Silver loyalty card checks 2 bags of 24 kg and 17 kg; the suitcase holds a power bank marked 20000 mAh, 3.7 V. Checked allowance is 23 kg, Silver members get 10 kg extra, excess fee 220,000 VND per kg (training figures). Draft record PS-8364 has the wrong power bank carriage and excess fee. Correct both fields and write an evidence-based report."},reference_title:{vi:"Quy định hàng nguy hiểm & biểu phí hành lý đã duyệt · PS-8364",en:"Approved dangerous goods rules & baggage tariff · PS-8364"},fields:[{id:"POWERBANK",label:{vi:"Phương án vận chuyển pin sạc dự phòng",en:"Power bank carriage"},initial:"CHECKED",expected:"CABIN",choices:["CHECKED","CABIN","FORBIDDEN"],reference:"Bảng quy định hàng nguy hiểm cho hành khách",hint:{vi:"Pin sạc dự phòng lithium bị cấm trong hành lý ký gửi; tính Wh để biết có được xách tay mà không cần phê duyệt.",en:"Lithium power banks are banned from checked baggage; compute Wh to see if cabin carriage needs approval."}},{id:"EXCESS_FEE",label:{vi:"Phí quá cước hành lý (VND)",en:"Excess baggage fee (VND)"},initial:"3960000",expected:"1760000",reference:"Biểu phí hành lý quá cước",ref_value:{vi:"Kiện 24 kg + 17 kg; tiêu chuẩn 23 kg; hội viên Bạc thêm 10 kg; 220.000 đồng/kg (mô phỏng)",en:"Bags 24 kg + 17 kg; allowance 23 kg; Silver extra 10 kg; 220,000 VND per kg (training)"},hint:{vi:"Cộng tiêu chuẩn của hội viên vào tiêu chuẩn hạng vé trước khi tính số kg vượt.",en:"Add the loyalty allowance to the fare allowance before computing the excess kilograms."}}],sop32:{vi:"Phí quá cước = (tổng trọng lượng ký gửi - tiêu chuẩn hạng vé - tiêu chuẩn cộng thêm của hội viên) x đơn giá/kg; mỗi kiện không quá 32 kg; năng lượng pin Wh = mAh x V / 1000 (số liệu mô phỏng).",en:"Excess fee = (total checked weight - fare allowance - loyalty extra allowance) x rate per kg; no bag over 32 kg; battery energy Wh = mAh x V / 1000 (training figures)."},context:{label:"DCS / PS-8364",metrics:[{label:{vi:"Hành lý ký gửi",en:"Checked bags"},value:"24 + 17 kg"},{label:{vi:"Tiêu chuẩn",en:"Allowance"},value:"23 + 10 kg"},{label:{vi:"Pin sạc dự phòng",en:"Power bank"},value:"20000 mAh / 3.7 V"}]},crisis:{vi:"Hành khách là người quen của một trưởng ca khác. Người này nhắn bạn: “Ghi tổng 33 kg cho khách để khỏi thu phí, còn cục sạc cứ để trong vali, máy soi ít khi phát hiện.”",en:"The passenger knows another duty manager, who messages you: “Enter 33 kg in total so there's no fee, and leave the power bank in the suitcase, screening rarely catches it.”"},options:{safe:{vi:"Ghi đúng cân thực tế, thu phí theo quy định, yêu cầu khách chuyển pin sạc sang hành lý xách tay; miễn giảm chỉ khi có phê duyệt trên hệ thống và báo trưởng ca phụ trách.",en:"Record the true weight, charge per tariff and have the power bank moved to cabin baggage; waivers only with system approval, and inform the duty manager in charge."},shortcut:{vi:"Ghi 33 kg như được nhắn và để pin sạc trong vali ký gửi cho nhanh.",en:"Enter 33 kg as asked and leave the power bank in the checked suitcase to save time."},wait:{vi:"Giữ hành lý ở quầy, không làm gì và chờ trưởng ca kia tự đến xử lý.",en:"Hold the bags at the counter, do nothing and wait for the other manager to come."}},questions:{vi:["Vì sao bạn đổi phương án vận chuyển pin sạc dự phòng? Phép tính Wh nào chứng minh lựa chọn đó?","Trình bày cách tính phí quá cước và cách xử lý khi có người yêu cầu ghi sai trọng lượng hành lý."],en:["Why did you change the power bank carriage? Which Wh calculation supports your choice?","Explain how you calculated the excess fee and how you handle a request to record a false baggage weight."]},hints:{vi:["Quy đổi dung lượng pin sang Wh rồi so với các ngưỡng trong bảng hàng nguy hiểm cho hành khách.","Theo SOP mục 3.2: xác định tổng tiêu chuẩn được hưởng trước khi trừ khỏi tổng trọng lượng.","Đọc lại SOP mục 4.2: trọng lượng và hàng nguy hiểm phải khai đúng, mọi miễn giảm cần phê duyệt."],en:["Convert the battery capacity to Wh and compare it with the passenger dangerous goods thresholds.","Per SOP 3.2: work out the total allowance before subtracting it from the total weight.","Re-read SOP 4.2: weight and dangerous goods must be declared truthfully; waivers need approval."]}},learning:{summary:{vi:"Nhân viên phục vụ mặt đất và thủ tục hàng không làm thủ tục cho hành khách, kiểm tra giấy tờ đi lại, chấp nhận hành lý, nhận diện hàng nguy hiểm, thu phí dịch vụ, điều phối lên tàu bay và hỗ trợ hành khách cần trợ giúp đặc biệt. Công việc ảnh hưởng trực tiếp đến an toàn bay, đúng giờ khai thác và trải nghiệm khách. Nghề đòi hỏi thao tác hệ thống nhanh, ngoại ngữ, kiến thức quy định quốc tế và bản lĩnh giữ nguyên tắc trước áp lực.",en:"An airport ground handling and passenger service agent checks in passengers, verifies travel documents, accepts baggage, identifies dangerous goods, collects service fees, runs boarding and assists passengers needing special help. The work directly affects flight safety, on-time performance and passenger experience. The role needs fast system skills, languages, knowledge of international rules and the firmness to hold to procedure under pressure."},responsibilities:{vi:["Làm thủ tục, kiểm tra hộ chiếu, thị thực và điều kiện nhập cảnh của điểm đến.","Chấp nhận hành lý, cân, dán thẻ, thu phí quá cước theo biểu phí của hãng.","Hỏi và nhận diện hàng nguy hiểm, hướng dẫn hành khách xử lý pin lithium, chất lỏng.","Điều phối cửa ra tàu bay, đối chiếu số khách và đóng chuyến đúng giờ.","Hỗ trợ hành khách cần trợ giúp đặc biệt, xử lý chậm, hủy chuyến và hành lý thất lạc."],en:["Check in passengers and verify passports, visas and destination entry rules.","Accept, weigh and tag baggage and collect excess fees per the airline tariff.","Ask about and identify dangerous goods and guide passengers on lithium batteries and liquids.","Run the boarding gate, reconcile passenger counts and close the flight on time.","Assist passengers with reduced mobility and handle delays, cancellations and mishandled bags."]},competencies:[{name:{vi:"Nhận diện hàng nguy hiểm",en:"Dangerous goods awareness"},desc:{vi:"Hỏi đúng câu hỏi, tính Wh của pin và áp ngưỡng cho phép, cấm, cần phê duyệt.",en:"Ask the right questions, compute battery Wh and apply allowed, forbidden and approval thresholds."}},{name:{vi:"Chấp nhận hành lý",en:"Baggage acceptance"},desc:{vi:"Tính đúng tiêu chuẩn, phí quá cước, giới hạn kiện và dán thẻ đúng điểm đến.",en:"Apply allowances, excess fees and piece limits correctly and tag to the right destination."}},{name:{vi:"Kiểm tra giấy tờ đi lại",en:"Travel document checks"},desc:{vi:"Đối chiếu hạn hộ chiếu, thị thực, điều kiện nhập cảnh trước khi cấp thẻ lên tàu.",en:"Check passport validity, visas and entry conditions before issuing a boarding pass."}},{name:{vi:"Giao tiếp dưới áp lực",en:"Communication under pressure"},desc:{vi:"Giải thích quy định rõ ràng, lịch sự với hành khách khó tính và giữ hàng chờ thông suốt.",en:"Explain rules clearly and politely to difficult passengers and keep the queue moving."}},{name:{vi:"Tuân thủ an toàn, an ninh",en:"Safety and security compliance"},desc:{vi:"Từ chối ghi sai trọng lượng, không nhận hộ hành lý và báo ngay dấu hiệu bất thường.",en:"Refuse false weights, never accept bags for others and report anything unusual at once."}}],knowledge:{vi:["Phụ lục 18 Công ước Chicago và Hướng dẫn kỹ thuật ICAO Doc 9284 về vận chuyển an toàn hàng nguy hiểm bằng đường hàng không.","Quy định hàng nguy hiểm IATA (DGR) cho hành khách: pin lithium, pin sạc dự phòng, ngưỡng 100 Wh và 160 Wh.","Luật Hàng không dân dụng Việt Nam năm 2006, sửa đổi, bổ sung năm 2014.","Công ước Montreal 1999 về trách nhiệm của người vận chuyển đối với hành khách và hành lý.","Quy định hiện hành về an ninh hàng không và kiểm tra giấy tờ đi lại tại sân bay."],en:["Annex 18 to the Chicago Convention and ICAO Doc 9284 Technical Instructions on the safe transport of dangerous goods by air.","IATA Dangerous Goods Regulations for passengers: lithium batteries, power banks, the 100 Wh and 160 Wh thresholds.","Vietnam Civil Aviation Law of 2006, amended in 2014.","Montreal Convention 1999 on carrier liability for passengers and baggage.","Current aviation security rules and travel document checks at airports."]},tools:["Hệ thống kiểm soát khởi hành (DCS)","Cân và băng chuyền hành lý","Máy in thẻ lên tàu và thẻ hành lý","Hệ thống tra cứu điều kiện nhập cảnh","Hệ thống truy tìm hành lý thất lạc"],kpis:{vi:["Thời gian chờ làm thủ tục trung bình của hành khách.","Tỷ lệ đóng cửa lên tàu bay đúng giờ.","Số hành lý thất lạc hoặc dán sai thẻ trên 1000 hành khách.","Số vụ hàng nguy hiểm bị phát hiện sau quầy thủ tục (mục tiêu bằng 0)."],en:["Average passenger check-in waiting time.","Share of boarding gates closed on time.","Mishandled or mistagged bags per 1000 passengers.","Dangerous goods cases found after check-in (target zero)."]},day:[{time:"04:30",vi:"Nhận ca, nghe briefing về chuyến bay, khách đặc biệt và thông báo an toàn mới.",en:"Start the shift with a briefing on flights, special passengers and new safety notices."},{time:"05:00",vi:"Mở quầy thủ tục, kiểm tra giấy tờ và chấp nhận hành lý chuyến sáng.",en:"Open check-in, verify documents and accept baggage for the morning flight."},{time:"07:30",vi:"Điều phối cửa ra tàu bay, đối chiếu số khách và đóng chuyến.",en:"Run the boarding gate, reconcile passenger numbers and close the flight."},{time:"10:00",vi:"Xử lý chuyến chậm: thông báo cho khách, sắp xếp suất ăn và đổi chuyến.",en:"Handle a delayed flight: inform passengers, arrange meals and rebook."},{time:"12:30",vi:"Lập báo cáo ca, ghi nhận sự cố hàng nguy hiểm và bàn giao quầy.",en:"Write the shift report, log dangerous goods events and hand over the counter."}],mistakes:{vi:["Để pin sạc dự phòng trong hành lý ký gửi vì không hỏi kỹ hành khách.","Quên cộng tiêu chuẩn hành lý của hội viên nên thu phí quá cước sai.","Không kiểm tra hạn hộ chiếu, thị thực khiến khách bị từ chối nhập cảnh ở điểm đến."],en:["Leaving a power bank in checked baggage because the passenger was not asked properly.","Forgetting the loyalty allowance and charging the wrong excess fee.","Not checking passport or visa validity so the passenger is refused entry at destination."]},career:[{vi:"Nhân viên thủ tục hàng không",en:"Check-in agent"},{vi:"Nhân viên phục vụ hành khách chính, giám sát cửa ra tàu bay",en:"Senior passenger service and gate agent"},{vi:"Trưởng ca Phục vụ hành khách",en:"Passenger services duty manager"},{vi:"Quản lý dịch vụ mặt đất tại sân bay",en:"Airport ground services manager"}],glossary:[{term:"DCS",vi:"Hệ thống kiểm soát khởi hành dùng để làm thủ tục, chấp nhận hành lý và đóng chuyến.",en:"Departure control system for check-in, baggage acceptance and flight closing."},{term:"Wh",vi:"Oát giờ, đơn vị năng lượng của pin, bằng mAh nhân điện áp chia 1000.",en:"Watt-hour, a battery energy unit equal to mAh times voltage divided by 1000."},{term:"Excess baggage",vi:"Hành lý vượt tiêu chuẩn miễn cước, phải trả phí theo biểu phí của hãng.",en:"Baggage above the free allowance, charged per the airline tariff."},{term:"PRM",vi:"Hành khách hạn chế khả năng di chuyển, cần hỗ trợ như xe lăn, người dẫn.",en:"Passenger with reduced mobility who needs help such as a wheelchair or escort."},{term:"Offload",vi:"Đưa hành khách hoặc hành lý ra khỏi chuyến bay khi không đủ điều kiện vận chuyển.",en:"Removing a passenger or bag from a flight when carriage conditions are not met."}],quiz:[{q:{vi:"Pin sạc dự phòng ghi 26800 mAh, 3.7 V. Theo ngưỡng IATA cho hành khách, phương án đúng là gì?",en:"A power bank is marked 26800 mAh, 3.7 V. Under IATA passenger thresholds, what is correct?"},options:{vi:["Cấm vận chuyển","Được ký gửi","Xách tay, không cần phê duyệt","Xách tay, cần hãng phê duyệt"],en:["Forbidden","May be checked","Cabin only, no approval needed","Cabin only, airline approval needed"]},answer:2,explain:{vi:"26800 x 3.7 / 1000 = 99.16 Wh, không quá 100 Wh nên được xách tay mà không cần phê duyệt; không được ký gửi.",en:"26800 x 3.7 / 1000 = 99.16 Wh, not above 100 Wh, so cabin carriage needs no approval; never checked."}},{q:{vi:"Pin lithium dự phòng ở mức năng lượng nào cần hãng hàng không phê duyệt?",en:"At what energy level does a spare lithium battery need airline approval?"},options:{vi:["Từ 50 đến 100 Wh","Trên 100 đến 160 Wh","Trên 160 Wh","Mọi mức năng lượng"],en:["50 to 100 Wh","Above 100 up to 160 Wh","Above 160 Wh","Any energy level"]},answer:1,explain:{vi:"Trên 100 Wh đến 160 Wh cần phê duyệt của hãng; trên 160 Wh bị cấm với hành khách.",en:"Above 100 Wh up to 160 Wh needs airline approval; above 160 Wh is forbidden for passengers."}},{q:{vi:"Một kiện hành lý ký gửi nặng 35 kg. Bạn xử lý thế nào?",en:"A checked bag weighs 35 kg. What do you do?"},options:{vi:["Dán thẻ nặng và nhận bình thường","Thu thêm phí rồi nhận","Nhờ nhân viên bốc xếp tự xử lý","Đề nghị khách chia lại hành lý vì vượt giới hạn kiện"],en:["Add a heavy tag and accept it","Charge extra and accept it","Let the loaders deal with it","Ask the passenger to repack because it exceeds the piece limit"]},answer:3,explain:{vi:"Giới hạn 32 kg mỗi kiện bảo vệ an toàn lao động cho nhân viên bốc xếp; kiện nặng hơn phải chia lại.",en:"The 32 kg piece limit protects baggage handlers; heavier bags must be repacked."}},{q:{vi:"Một người lạ ở sảnh nhờ hành khách ký gửi hộ một túi quà. Hành khách hỏi ý kiến bạn. Bạn trả lời thế nào?",en:"A stranger in the hall asks a passenger to check in a gift bag for them. The passenger asks you. What do you say?"},options:{vi:["Không nhận hộ hành lý của người khác và báo an ninh","Nhận nếu túi nhẹ","Mở túi xem rồi nhận","Nhận nếu người lạ để lại số điện thoại"],en:["Do not carry others' bags and inform security","Accept it if it is light","Open it, check, then accept","Accept it if the stranger leaves a phone number"]},answer:0,explain:{vi:"Hành khách phải tự đóng gói và chịu trách nhiệm hành lý; nhận hộ người lạ là rủi ro an ninh nghiêm trọng.",en:"Passengers must pack and own their baggage; carrying bags for strangers is a serious security risk."}}]}},"KK-796":{scenario:{company:"Công ty Du lịch Hành Trình Ngọc Lam",supervisor:{name:"Phan Nhật Linh",role:{vi:"Trưởng nhóm Hướng dẫn viên",en:"Head of Tour Guides"}},ref_code:"GD-1407",title:{vi:"Thuyết minh chính xác. Quyết toán minh bạch. An toàn trên hết.",en:"Accurate commentary. Transparent settlement. Safety first."},brief:{vi:"Bạn dẫn đoàn 18 khách Pháp (15 người lớn, 3 trẻ em 8-10 tuổi) tham quan Quần thể danh thắng Tràng An. Vé tham quan kèm đò: người lớn 250.000 đồng, trẻ em bằng 50% giá người lớn; hướng dẫn viên có thẻ hành nghề được miễn vé (số liệu mô phỏng). Thẻ thuyết minh nháp GD-1407 ghi sai loại hình di sản và bảng quyết toán ghi sai tổng tiền vé. Sửa hai trường rồi lập báo cáo có căn cứ.",en:"You are guiding 18 French guests (15 adults, 3 children aged 8-10) at the Trang An Landscape Complex. Entry with boat ride: adults 250,000 VND, children 50% of the adult price; a licensed guide enters free (training figures). Draft commentary card GD-1407 has the wrong heritage type and the settlement sheet has the wrong ticket total. Correct both fields and write an evidence-based report."},reference_title:{vi:"Hồ sơ điểm đến & bảng quyết toán đã duyệt · GD-1407",en:"Approved destination file & settlement sheet · GD-1407"},fields:[{id:"HERITAGE",label:{vi:"Loại hình di sản thế giới UNESCO",en:"UNESCO World Heritage type"},initial:"Natural",expected:"Mixed",choices:["Cultural","Natural","Mixed"],reference:"Hồ sơ điểm đến đã kiểm chứng",hint:{vi:"Xem Tràng An được ghi danh năm 2014 theo những tiêu chí nào: chỉ tiêu chí thiên nhiên hay cả tiêu chí văn hóa.",en:"Check which criteria Trang An was inscribed under in 2014: natural criteria only, or cultural ones as well."}},{id:"TICKET_TOTAL",label:{vi:"Tổng tiền vé tham quan (VND)",en:"Total entry tickets (VND)"},initial:"4750000",expected:"4125000",reference:"Bảng quyết toán tạm ứng tour",ref_value:{vi:"15 người lớn x 250.000 đồng; 3 trẻ em giá 50%; hướng dẫn viên miễn vé (mô phỏng)",en:"15 adults x 250,000 VND; 3 children at 50%; guide free (training)"},hint:{vi:"Tính riêng vé người lớn, vé trẻ em và không mua vé cho hướng dẫn viên có thẻ.",en:"Price adult and child tickets separately and buy no ticket for the licensed guide."}}],sop32:{vi:"Tổng tiền vé = số người lớn x giá người lớn + số trẻ em x giá người lớn x 50%; hướng dẫn viên có thẻ hành nghề không mua vé; chỉ quyết toán khoản có vé, hóa đơn hợp lệ (số liệu mô phỏng).",en:"Ticket total = adults x adult price + children x adult price x 50%; a licensed guide buys no ticket; settle only items with valid tickets or invoices (training figures)."},context:{label:"TOUR FILE / GD-1407",metrics:[{label:{vi:"Người lớn / trẻ em",en:"Adults / children"},value:"15 / 3"},{label:{vi:"Giá vé người lớn",en:"Adult ticket"},value:"250,000 VND"},{label:{vi:"Giá vé trẻ em",en:"Child ticket"},value:"50%"}]},crisis:{vi:"Có cảnh báo dông lốc, Ban quản lý tạm dừng một tuyến đò. Một người chở đò tư nhân mời đoàn đi tuyến khác ngoài bến, không có áo phao, giá rẻ; trưởng đoàn khách nói: “Đi thôi, đừng để khách thất vọng.”",en:"A thunderstorm warning is issued and the site management suspends one boat route. A private boatman offers another route outside the pier, cheap and with no life jackets; the group leader says: “Let's go, don't disappoint the guests.”"},options:{safe:{vi:"Không đưa khách lên đò không phép, thiếu áo phao; báo điều hành tour, giải thích rõ với khách và đổi sang hoạt động thay thế an toàn theo hướng dẫn của Ban quản lý.",en:"Do not put guests on an unlicensed boat without life jackets; inform tour operations, explain clearly to guests and switch to a safe alternative per site management guidance."},shortcut:{vi:"Cho đoàn đi đò tư nhân cho đúng lịch trình và dặn khách ngồi yên trên đò.",en:"Take the private boat to keep the itinerary and tell guests to sit still."},wait:{vi:"Để trưởng đoàn khách tự quyết, mình đứng chờ ở bến và không báo ai.",en:"Let the group leader decide, wait at the pier and inform no one."}},questions:{vi:["Vì sao bạn sửa loại hình di sản trên thẻ thuyết minh? Căn cứ nào chứng minh lựa chọn đó?","Trình bày cách tính tổng tiền vé và cách xử lý khi điều kiện an toàn trên tuyến tham quan không bảo đảm."],en:["Why did you change the heritage type on the commentary card? Which source supports your choice?","Explain how you calculated the ticket total and how you act when safety conditions on a route are not met."]},hints:{vi:["Đối chiếu thẻ thuyết minh với hồ sơ ghi danh của UNESCO, chú ý nhóm tiêu chí được công nhận.","Theo SOP mục 3.2: tách khách theo người lớn, trẻ em và kiểm tra ai được miễn vé.","Đọc lại SOP mục 4.2: an toàn của khách đứng trên lịch trình, mọi thay đổi phải báo điều hành."],en:["Compare the card with the UNESCO inscription file and note which criteria groups were recognised.","Per SOP 3.2: split guests into adults and children and check who enters free.","Re-read SOP 4.2: guest safety comes before the itinerary; report every change to operations."]}},learning:{summary:{vi:"Hướng dẫn viên du lịch quốc tế dẫn đoàn khách nước ngoài hoặc khách Việt Nam ra nước ngoài, thuyết minh lịch sử, văn hóa, thiên nhiên bằng ngoại ngữ, giữ lịch trình, quản lý đoàn, quyết toán chi phí và xử lý sự cố. Người hướng dẫn viên là gương mặt của điểm đến và của doanh nghiệp, chịu trách nhiệm trực tiếp về an toàn và trải nghiệm của khách. Nghề đòi hỏi kiến thức rộng, kiểm chứng thông tin, ngoại ngữ vững, sức khỏe tốt và đạo đức nghề nghiệp.",en:"An international tour guide leads foreign visitors in Vietnam or Vietnamese travellers abroad, giving commentary on history, culture and nature in a foreign language, keeping the itinerary, managing the group, settling expenses and handling incidents. The guide is the face of the destination and the company and is directly responsible for guest safety and experience. The role needs broad, verified knowledge, strong languages, good stamina and professional ethics."},responsibilities:{vi:["Nghiên cứu, kiểm chứng nội dung thuyết minh cho từng điểm đến trước mỗi tour.","Đón khách, kiểm đếm quân số, giữ lịch trình và phối hợp xe, nhà hàng, khách sạn.","Thuyết minh bằng ngoại ngữ, điều chỉnh nội dung theo văn hóa và mối quan tâm của khách.","Bảo đảm an toàn đoàn, theo dõi thời tiết, xử lý khách ốm, lạc, mất giấy tờ.","Quyết toán tạm ứng có chứng từ hợp lệ và báo cáo tour cho điều hành."],en:["Research and verify commentary for each destination before every tour.","Meet guests, run head counts, keep the itinerary and coordinate coaches, restaurants and hotels.","Deliver commentary in a foreign language, adapting to guests' culture and interests.","Keep the group safe, watch the weather and handle illness, lost guests and lost documents.","Settle the cash advance with valid receipts and report on the tour to operations."]},competencies:[{name:{vi:"Thuyết minh có kiểm chứng",en:"Verified commentary"},desc:{vi:"Dùng nguồn chính thống, phân biệt sự kiện với truyền thuyết và cập nhật thông tin mới.",en:"Use official sources, separate facts from legends and keep information current."}},{name:{vi:"Quản lý đoàn",en:"Group management"},desc:{vi:"Kiểm đếm quân số, điều phối thời gian và giữ đoàn gắn kết, đúng giờ.",en:"Run head counts, manage time and keep the group together and on schedule."}},{name:{vi:"Giao tiếp liên văn hóa",en:"Cross-cultural communication"},desc:{vi:"Hiểu thói quen, kỳ vọng của từng thị trường khách và truyền đạt văn hóa Việt Nam tự nhiên.",en:"Understand each market's habits and expectations and present Vietnamese culture naturally."}},{name:{vi:"An toàn & sơ cứu",en:"Safety & first aid"},desc:{vi:"Đánh giá rủi ro tại điểm, sơ cứu cơ bản và kích hoạt quy trình khẩn cấp đúng lúc.",en:"Assess on-site risks, give basic first aid and trigger emergency procedures in time."}},{name:{vi:"Minh bạch tài chính",en:"Financial transparency"},desc:{vi:"Quyết toán đúng chứng từ, từ chối hoa hồng ép khách mua hàng và báo cáo trung thực.",en:"Settle with correct receipts, refuse commissions that pressure guests to buy and report honestly."}}],knowledge:{vi:["Luật Du lịch số 09/2017/QH14: thẻ hướng dẫn viên quốc tế, nội địa, tại điểm và nghĩa vụ của hướng dẫn viên.","Công ước UNESCO năm 1972 về bảo vệ di sản văn hóa và thiên nhiên thế giới: di sản văn hóa, thiên nhiên, hỗn hợp.","Luật Di sản văn hóa năm 2024 và nội quy tham quan tại các khu di tích, danh thắng.","Lịch sử, văn hóa Việt Nam và các di sản thế giới như Huế, Hội An, Mỹ Sơn, Tràng An, Vịnh Hạ Long.","Sơ cấp cứu cơ bản và quy trình xử lý khách lạc, mất giấy tờ, tai nạn trong hành trình."],en:["Tourism Law No. 09/2017/QH14: international, domestic and on-site guide cards and guides' duties.","UNESCO 1972 World Heritage Convention: cultural, natural and mixed heritage.","Law on Cultural Heritage of 2024 and visitor rules at monuments and scenic sites.","Vietnamese history and culture and World Heritage sites such as Hue, Hoi An, My Son, Trang An and Ha Long Bay.","Basic first aid and procedures for lost guests, lost documents and accidents on tour."]},tools:["Bộ micro và tai nghe thuyết minh không dây","Ứng dụng nhắn tin nhóm đoàn","Bộ sơ cứu","Bảng quyết toán tạm ứng tour","Ứng dụng bản đồ và dự báo thời tiết"],kpis:{vi:["Điểm đánh giá của khách sau tour.","Tỷ lệ đúng giờ tại các điểm trong lịch trình.","Số sự cố an toàn trong tour (mục tiêu bằng 0).","Quyết toán đúng hạn, không sai sót chứng từ."],en:["Guest rating after the tour.","On-time rate at itinerary stops.","Safety incidents during the tour (target zero).","On-time settlement with no receipt errors."]},day:[{time:"07:00",vi:"Xem dự báo thời tiết, xác nhận xe, nhà hàng và vé tham quan trong ngày.",en:"Check the forecast and confirm the coach, restaurants and entry tickets for the day."},{time:"08:00",vi:"Đón khách tại khách sạn, kiểm đếm quân số, giới thiệu lịch trình và lưu ý an toàn.",en:"Meet guests at the hotel, count heads, present the plan and safety notes."},{time:"09:30",vi:"Thuyết minh tại điểm tham quan, mua vé theo đúng loại khách và giữ đoàn đúng giờ.",en:"Give site commentary, buy tickets by guest category and keep the group on time."},{time:"12:00",vi:"Ăn trưa cùng đoàn, kiểm tra yêu cầu ăn kiêng và dị ứng của khách.",en:"Have lunch with the group and check dietary and allergy needs."},{time:"17:00",vi:"Đưa khách về khách sạn, ghi nhận phản hồi, quyết toán chi phí và báo cáo điều hành.",en:"Return guests to the hotel, record feedback, settle costs and report to operations."}],mistakes:{vi:["Thuyết minh theo trí nhớ, nêu sai năm ghi danh hoặc loại hình di sản.","Mua vé người lớn cho trẻ em hoặc mua vé cho hướng dẫn viên đã được miễn.","Chiều khách tham gia hoạt động thiếu an toàn hoặc đưa khách vào điểm mua sắm ép giá để hưởng hoa hồng."],en:["Giving commentary from memory with wrong inscription years or heritage types.","Buying adult tickets for children or a ticket for a guide who enters free.","Letting guests join unsafe activities or taking them to overpriced shops for commission."]},career:[{vi:"Hướng dẫn viên tại điểm hoặc nội địa",en:"On-site or domestic guide"},{vi:"Hướng dẫn viên du lịch quốc tế",en:"International tour guide"},{vi:"Hướng dẫn viên chính tuyến cao cấp",en:"Senior lead guide for premium routes"},{vi:"Trưởng nhóm hướng dẫn viên, quản lý chất lượng dịch vụ",en:"Head of guides and service quality manager"}],glossary:[{term:"Mixed heritage",vi:"Di sản thế giới hỗn hợp, được công nhận đồng thời theo tiêu chí văn hóa và tiêu chí thiên nhiên.",en:"World Heritage site recognised under both cultural and natural criteria."},{term:"Tour leader",vi:"Trưởng đoàn đại diện cho khách hoặc công ty gửi khách, phối hợp với hướng dẫn viên địa phương.",en:"Group leader representing the guests or the sending company, working with the local guide."},{term:"Head count",vi:"Kiểm đếm quân số đoàn tại mỗi điểm dừng để không bỏ sót khách.",en:"Counting the group at each stop so no guest is left behind."},{term:"Cash advance",vi:"Khoản tạm ứng công ty giao cho hướng dẫn viên để chi trả dịch vụ trong tour.",en:"Money the company advances to the guide to pay for services on tour."},{term:"Commentary",vi:"Bài thuyết minh của hướng dẫn viên về lịch sử, văn hóa, thiên nhiên của điểm đến.",en:"The guide's narration on a destination's history, culture and nature."}],quiz:[{q:{vi:"Di sản thế giới nào ở Việt Nam là di sản hỗn hợp văn hóa và thiên nhiên?",en:"Which World Heritage site in Vietnam is a mixed cultural and natural site?"},options:{vi:["Vịnh Hạ Long","Quần thể danh thắng Tràng An","Phố cổ Hội An","Vườn quốc gia Phong Nha - Kẻ Bàng"],en:["Ha Long Bay","Trang An Landscape Complex","Hoi An Ancient Town","Phong Nha - Ke Bang National Park"]},answer:1,explain:{vi:"Tràng An được ghi danh năm 2014 là di sản hỗn hợp; Hội An là di sản văn hóa, Hạ Long và Phong Nha - Kẻ Bàng là di sản thiên nhiên.",en:"Trang An was inscribed in 2014 as a mixed site; Hoi An is cultural, Ha Long and Phong Nha - Ke Bang are natural."}},{q:{vi:"Đoàn 10 người lớn và 4 trẻ em; vé người lớn 200.000 đồng, trẻ em 50%, hướng dẫn viên miễn vé. Tổng tiền vé là bao nhiêu?",en:"A group of 10 adults and 4 children; adult ticket 200,000 VND, children 50%, guide free. What is the ticket total?"},options:{vi:["2.400.000 đồng","2.800.000 đồng","3.000.000 đồng","2.600.000 đồng"],en:["2,400,000 VND","2,800,000 VND","3,000,000 VND","2,600,000 VND"]},answer:0,explain:{vi:"10 x 200.000 + 4 x 100.000 = 2.000.000 + 400.000 = 2.400.000 đồng; hướng dẫn viên không mua vé.",en:"10 x 200,000 + 4 x 100,000 = 2,000,000 + 400,000 = 2,400,000 VND; the guide buys no ticket."}},{q:{vi:"Một cửa hàng đề nghị trả bạn 20% hoa hồng nếu bạn giới thiệu với khách rằng hàng của họ là đồ thủ công làng nghề, dù nguồn gốc không rõ. Bạn làm gì?",en:"A shop offers you 20% commission if you tell guests its goods are village handicrafts, though their origin is unclear. What do you do?"},options:{vi:["Nhận vì khách tự quyết định mua","Nhận nhưng không giới thiệu nhiều","Đưa khách đến rồi để cửa hàng tự nói","Từ chối, không giới thiệu sai và báo điều hành"],en:["Accept because guests choose to buy","Accept but promote it less","Bring guests and let the shop talk","Refuse, never mislead guests and report to operations"]},answer:3,explain:{vi:"Giới thiệu sai nguồn gốc hàng hóa là lừa dối khách và vi phạm đạo đức nghề hướng dẫn viên.",en:"Misrepresenting product origin deceives guests and breaches a guide's professional ethics."}},{q:{vi:"Khi kiểm đếm tại điểm dừng, bạn phát hiện thiếu một khách. Việc đầu tiên nên làm là gì?",en:"At a stop, the head count is one short. What should you do first?"},options:{vi:["Cho xe chạy, khách sẽ tự bắt taxi","Đăng thông báo lên mạng xã hội","Giữ đoàn tại điểm an toàn, liên lạc với khách và báo điều hành, ban quản lý điểm","Chờ đến hết ngày rồi báo cáo"],en:["Leave; the guest will take a taxi","Post a notice on social media","Keep the group at a safe spot, contact the guest and alert operations and site management","Wait until the end of the day, then report"]},answer:2,explain:{vi:"Giữ đoàn ổn định, liên lạc ngay và kích hoạt hỗ trợ của điều hành, ban quản lý giúp tìm khách nhanh và an toàn.",en:"Keeping the group settled, calling at once and getting operations and site staff involved finds the guest quickly and safely."}}]}},"KK-797":{scenario:{company:"Khách sạn Hạc Trắng Bờ Hồ",supervisor:{name:"Ngô Thị Thu Trang",role:{vi:"Giám đốc Khối Phòng",en:"Rooms Division Manager"}},ref_code:"HK-2611",title:{vi:"Đúng trạng thái phòng. Đúng nhân lực. Đúng chuẩn vệ sinh.",en:"Right room status. Right staffing. Right hygiene standard."},brief:{vi:"Bạn chốt kế hoạch buồng phòng HK-2611 cho ca sáng mai: dự báo 70 phòng khách trả và 98 phòng khách ở tiếp. Định mức mô phỏng: phòng khách trả 45 phút, phòng ở tiếp 25 phút; mỗi nhân viên buồng có 420 phút làm phòng thực tế trong ca 8 giờ. Phòng 1603 bị thấm nước trần, kỹ thuật báo cần sửa trên 48 giờ. Sửa trạng thái phòng 1603 và số nhân viên buồng cần phân công, rồi lập báo cáo có căn cứ.",en:"You are finalising housekeeping plan HK-2611 for tomorrow's morning shift: 70 departure rooms and 98 stayover rooms are forecast. Training standards: 45 minutes per departure, 25 minutes per stayover; each room attendant has 420 minutes of actual cleaning time in an 8-hour shift. Room 1603 has a ceiling leak and engineering needs more than 48 hours to fix it. Correct the status of room 1603 and the number of attendants, then write an evidence-based report."},reference_title:{vi:"Quy định trạng thái phòng & định mức lao động đã duyệt · HK-2611",en:"Approved room status rules & labour standards · HK-2611"},fields:[{id:"ROOM_STATUS",label:{vi:"Trạng thái phòng 1603",en:"Room 1603 status"},initial:"OOS",expected:"OOO",choices:["VD","OOS","OOO"],reference:"Quy định mã trạng thái phòng",hint:{vi:"Phòng phải sửa chữa lớn, kéo dài và không thể bán cần rút khỏi quỹ phòng bán, khác với lỗi nhỏ tạm thời.",en:"A room needing major, lengthy repair that cannot be sold must leave sellable inventory, unlike a minor temporary issue."}},{id:"RA_COUNT",label:{vi:"Số nhân viên buồng ca sáng",en:"Room attendants for the morning shift"},initial:"12",expected:"14",reference:"Bảng định mức lao động buồng phòng",ref_value:{vi:"70 phòng khách trả x 45 phút; 98 phòng ở tiếp x 25 phút; 420 phút mỗi nhân viên",en:"70 departures x 45 minutes; 98 stayovers x 25 minutes; 420 minutes per attendant"},hint:{vi:"Dùng thời gian làm phòng thực tế, không dùng cả 8 giờ ca, và làm tròn lên số nguyên.",en:"Use actual cleaning time, not the full 8-hour shift, and round up to a whole number."}}],sop32:{vi:"Số nhân viên buồng = (số phòng khách trả x 45 + số phòng ở tiếp x 25) / 420 phút làm phòng thực tế mỗi ca, làm tròn lên số nguyên; phòng sửa chữa dài ngày không đưa vào kế hoạch (định mức mô phỏng).",en:"Room attendants = (departures x 45 + stayovers x 25) / 420 actual cleaning minutes per shift, rounded up to a whole number; long-repair rooms are excluded from the plan (training standards)."},context:{label:"PMS HSK / HK-2611",metrics:[{label:{vi:"Phòng khách trả",en:"Departures"},value:"70"},{label:{vi:"Phòng ở tiếp",en:"Stayovers"},value:"98"},{label:{vi:"Phút làm phòng mỗi ca",en:"Cleaning minutes per shift"},value:"420"}]},crisis:{vi:"Khách phòng 1208 báo có rệp giường và gửi ảnh. Quản lý tiền sảnh nhắn: “Tối nay hết phòng, xịt thuốc nhanh rồi bán lại 1208 cho khách đến muộn, đừng ghi vào sổ để khỏi ảnh hưởng điểm đánh giá.”",en:"The guest in room 1208 reports bed bugs and sends photos. The front office manager writes: “We're full tonight. Spray it quickly and resell 1208 to a late arrival, and don't log it so our ratings aren't hurt.”"},options:{safe:{vi:"Khóa phòng 1208 không bán, xử lý theo quy trình kiểm soát côn trùng với đơn vị chuyên nghiệp, báo Giám đốc Khối Phòng, ghi sổ đầy đủ và đề xuất phòng thay thế cho khách.",en:"Block room 1208 from sale, treat it under the pest control procedure with a licensed contractor, inform the Rooms Division Manager, log it fully and offer the guest another room."},shortcut:{vi:"Xịt thuốc nhanh, bán lại phòng 1208 tối nay và không ghi vào sổ.",en:"Spray quickly, resell room 1208 tonight and leave it out of the log."},wait:{vi:"Để phòng 1208 nguyên trạng và chờ ca sau tự quyết định.",en:"Leave room 1208 as it is and let the next shift decide."}},questions:{vi:["Vì sao bạn đổi mã trạng thái phòng 1603? Thông tin nào của bộ phận kỹ thuật chứng minh lựa chọn đó?","Trình bày cách tính số nhân viên buồng và cách xử lý khi bị yêu cầu bán lại phòng có côn trùng gây hại."],en:["Why did you change the status code of room 1603? Which engineering information supports your choice?","Explain how you calculated the number of attendants and how you handle pressure to resell a room with pests."]},hints:{vi:["Đọc thời gian sửa chữa dự kiến của kỹ thuật rồi đối chiếu với định nghĩa từng mã trạng thái phòng.","Theo SOP mục 3.2: quy đổi khối lượng phòng ra phút, chia cho phút làm phòng thực tế và làm tròn lên.","Đọc lại SOP mục 4.2: phòng có côn trùng gây hại phải khóa, xử lý và ghi nhận, mọi áp lực bán phải báo cáo."],en:["Read engineering's expected repair time and compare it with the definition of each status code.","Per SOP 3.2: convert the room workload to minutes, divide by actual cleaning minutes and round up.","Re-read SOP 4.2: a room with pests must be blocked, treated and logged; escalate any pressure to sell it."]}},learning:{summary:{vi:"Quản lý buồng phòng khách sạn chịu trách nhiệm vệ sinh, bảo dưỡng và trình bày toàn bộ phòng khách, khu công cộng, đồ vải và giặt là. Người quản lý lập kế hoạch nhân lực theo dự báo, kiểm soát trạng thái phòng, hóa chất, chi phí, đồ thất lạc và phối hợp với tiền sảnh, kỹ thuật để phòng luôn sẵn sàng bán. Nghề đòi hỏi con mắt tỉ mỉ, kỹ năng điều phối đội ngũ lớn, hiểu an toàn lao động và kiên định với tiêu chuẩn vệ sinh.",en:"A hotel housekeeping manager is responsible for cleaning, upkeep and presentation of all guest rooms, public areas, linen and laundry. The manager plans staffing from forecasts, controls room status, chemicals, costs and lost property, and works with the front office and engineering so rooms are always ready to sell. The role needs an eye for detail, skill in leading a large team, knowledge of workplace safety and firmness on hygiene standards."},responsibilities:{vi:["Lập kế hoạch nhân lực, phân công khu vực theo dự báo phòng khách trả và ở tiếp.","Kiểm tra phòng, khu công cộng và bảo đảm phòng đạt chuẩn trước khi báo sạch.","Quản lý mã trạng thái phòng, đối chiếu chênh lệch với tiền sảnh và báo hỏng cho kỹ thuật.","Quản lý đồ vải, hóa chất, vật tư, đồ thất lạc và chi phí buồng phòng.","Huấn luyện tiêu chuẩn vệ sinh, an toàn hóa chất, an toàn lao động cho nhân viên."],en:["Plan staffing and assign sections from departure and stayover forecasts.","Inspect rooms and public areas and ensure standards before releasing rooms as clean.","Manage room status codes, resolve discrepancies with the front office and report defects to engineering.","Control linen, chemicals, supplies, lost property and housekeeping costs.","Train staff on cleaning standards, chemical safety and workplace safety."]},competencies:[{name:{vi:"Lập kế hoạch nhân lực",en:"Labour planning"},desc:{vi:"Quy đổi khối lượng phòng ra thời gian, phân công đủ người và kiểm soát giờ làm thêm.",en:"Convert room workload to time, staff adequately and control overtime."}},{name:{vi:"Quản lý trạng thái phòng",en:"Room status control"},desc:{vi:"Dùng đúng mã VC, VD, OC, OOO, OOS và xử lý chênh lệch với tiền sảnh kịp thời.",en:"Use VC, VD, OC, OOO and OOS correctly and resolve front office discrepancies quickly."}},{name:{vi:"Tiêu chuẩn vệ sinh",en:"Hygiene standards"},desc:{vi:"Kiểm tra phòng theo danh mục chuẩn, phát hiện côn trùng gây hại và lỗi bảo dưỡng.",en:"Inspect rooms with standard checklists and detect pests and maintenance defects."}},{name:{vi:"An toàn hóa chất & lao động",en:"Chemical & workplace safety"},desc:{vi:"Áp dụng phiếu an toàn hóa chất, trang bị bảo hộ và kỹ thuật làm việc an toàn.",en:"Apply safety data sheets, protective equipment and safe working techniques."}},{name:{vi:"Trung thực & trách nhiệm",en:"Honesty & accountability"},desc:{vi:"Ghi sổ đúng sự thật, không báo sạch khi chưa đạt và bảo vệ sức khỏe của khách.",en:"Log the truth, never release rooms that fail inspection and protect guest health."}}],knowledge:{vi:["TCVN 4391:2015 về xếp hạng khách sạn: yêu cầu về buồng ngủ, vệ sinh và dịch vụ buồng.","Luật An toàn, vệ sinh lao động số 84/2015/QH13: trang bị bảo hộ và huấn luyện an toàn cho người lao động.","Quản lý hóa chất theo phiếu an toàn hóa chất (SDS) và hệ thống GHS; không pha trộn chất tẩy chứa clo với axit.","Mã trạng thái phòng VC, VD, OC, OOO, OOS và quy trình đối chiếu với tiền sảnh.","Quản lý dịch hại tổng hợp (IPM) và quy trình xử lý rệp giường trong khách sạn.","Định mức lao động, mức tồn đồ vải chuẩn và chi phí buồng phòng trên mỗi đêm phòng có khách."],en:["TCVN 4391:2015 on hotel classification: requirements for guest rooms, hygiene and room service.","Occupational Safety and Health Law No. 84/2015/QH13: protective equipment and safety training.","Chemical management with safety data sheets (SDS) and GHS; never mix chlorine bleach with acid cleaners.","Room status codes VC, VD, OC, OOO and OOS and the front office reconciliation process.","Integrated pest management (IPM) and the bed bug response procedure in hotels.","Labour standards, linen par levels and housekeeping cost per occupied room."]},tools:["Phân hệ buồng phòng trên PMS","Ứng dụng phân công và kiểm tra phòng di động","Hệ thống quản lý đồ vải và giặt là","Bộ định lượng hóa chất tự động","Đèn soi kiểm tra vệ sinh và côn trùng"],kpis:{vi:["Tỷ lệ phòng đạt kiểm tra ngay lần đầu.","Thời gian trung bình làm một phòng khách trả.","Số phàn nàn về vệ sinh trên 1000 đêm phòng có khách.","Chi phí buồng phòng trên mỗi đêm phòng có khách."],en:["Share of rooms passing inspection the first time.","Average cleaning time per departure room.","Cleanliness complaints per 1000 occupied room nights.","Housekeeping cost per occupied room night."]},day:[{time:"07:30",vi:"Họp ca, phân công khu vực theo danh sách phòng khách trả, ở tiếp và phòng VIP.",en:"Hold the briefing and assign sections by departures, stayovers and VIP rooms."},{time:"09:00",vi:"Kiểm tra phòng VIP, phòng khách đến sớm và báo sạch cho tiền sảnh.",en:"Inspect VIP and early arrival rooms and release them to the front office."},{time:"11:00",vi:"Đối chiếu chênh lệch trạng thái phòng với tiền sảnh, báo hỏng cho kỹ thuật.",en:"Reconcile room status discrepancies with the front office and report defects to engineering."},{time:"14:00",vi:"Kiểm tra kho đồ vải, hóa chất, vật tư và sổ đồ thất lạc.",en:"Check linen, chemical and supply stores and the lost property log."},{time:"16:30",vi:"Chốt trạng thái phòng cuối ca, lập báo cáo và kế hoạch nhân lực ngày mai.",en:"Close room status for the shift, write the report and plan tomorrow's staffing."}],mistakes:{vi:["Ghi phòng sửa chữa dài ngày là OOS khiến phòng vẫn nằm trong quỹ phòng bán.","Tính nhân lực theo cả 8 giờ ca thay vì thời gian làm phòng thực tế.","Báo phòng sạch khi chưa kiểm tra hoặc bỏ qua dấu hiệu côn trùng gây hại."],en:["Coding a long-repair room as OOS so it stays in sellable inventory.","Planning staff on the full 8-hour shift instead of actual cleaning time.","Releasing rooms as clean without inspection or ignoring signs of pests."]},career:[{vi:"Nhân viên buồng phòng",en:"Room attendant"},{vi:"Giám sát buồng phòng",en:"Housekeeping supervisor"},{vi:"Quản lý buồng phòng",en:"Housekeeping manager"},{vi:"Giám đốc Khối Phòng",en:"Rooms division manager"}],glossary:[{term:"OOO",vi:"Out of order: phòng hỏng phải sửa chữa lớn, rút khỏi quỹ phòng bán trong thời gian sửa.",en:"Out of order: a room under major repair, removed from sellable inventory during the work."},{term:"OOS",vi:"Out of service: phòng tạm ngừng bán vì lỗi nhỏ, khắc phục nhanh, vẫn nằm trong quỹ phòng.",en:"Out of service: a room briefly held for a minor issue, fixed quickly and still in inventory."},{term:"Discrepancy",vi:"Chênh lệch trạng thái phòng giữa buồng phòng và tiền sảnh cần đối chiếu ngay.",en:"Room status mismatch between housekeeping and the front office that must be resolved at once."},{term:"Par level",vi:"Mức tồn đồ vải chuẩn, thường tính theo số bộ cho mỗi giường để luân chuyển giặt là.",en:"Standard linen stock, usually sets per bed, to keep laundry rotation running."},{term:"Turndown service",vi:"Dịch vụ chỉnh trang phòng buổi tối, chuẩn bị giường ngủ và tiện nghi cho khách.",en:"Evening service that prepares the bed and amenities for the guest."}],quiz:[{q:{vi:"Dự báo 40 phòng khách trả (45 phút) và 60 phòng ở tiếp (25 phút); mỗi nhân viên có 420 phút làm phòng. Cần bao nhiêu nhân viên buồng?",en:"Forecast 40 departures (45 minutes) and 60 stayovers (25 minutes); each attendant has 420 minutes. How many attendants are needed?"},options:{vi:["8 nhân viên","7 nhân viên","9 nhân viên","10 nhân viên"],en:["8 attendants","7 attendants","9 attendants","10 attendants"]},answer:0,explain:{vi:"40 x 45 + 60 x 25 = 3300 phút; 3300 / 420 = 7.86, làm tròn lên được 8 nhân viên.",en:"40 x 45 + 60 x 25 = 3300 minutes; 3300 / 420 = 7.86, rounded up to 8 attendants."}},{q:{vi:"Mã OOS khác OOO ở điểm nào?",en:"How does OOS differ from OOO?"},options:{vi:["OOS là phòng khách đang ở","OOS là phòng bẩn chờ dọn","OOS là phòng sửa chữa lớn dài ngày","OOS là lỗi nhỏ tạm thời, phòng vẫn trong quỹ phòng bán"],en:["OOS is an occupied room","OOS is a dirty room awaiting cleaning","OOS is a long major repair","OOS is a minor temporary issue; the room stays in inventory"]},answer:3,explain:{vi:"OOS dành cho lỗi nhỏ, khắc phục nhanh; OOO dành cho sửa chữa lớn và phòng bị rút khỏi quỹ phòng bán.",en:"OOS covers minor, quick fixes; OOO covers major repairs and removes the room from inventory."}},{q:{vi:"Nhân viên muốn pha chất tẩy chứa clo với chất tẩy cặn axit cho nhanh sạch. Bạn hướng dẫn thế nào?",en:"An attendant wants to mix chlorine bleach with an acid descaler to clean faster. What do you say?"},options:{vi:["Cho phép nếu mở cửa sổ","Cấm pha trộn vì sinh khí độc, dùng đúng hóa chất theo phiếu an toàn","Cho phép nếu đeo khẩu trang y tế","Để nhân viên tự chọn"],en:["Allow it if a window is open","Forbid it because it releases toxic gas; use chemicals per the safety data sheet","Allow it with a surgical mask","Let the attendant decide"]},answer:1,explain:{vi:"Clo trộn với axit giải phóng khí clo độc; chỉ dùng hóa chất đúng hướng dẫn và có bảo hộ phù hợp.",en:"Bleach mixed with acid releases toxic chlorine gas; use chemicals only as instructed with proper protection."}},{q:{vi:"Nhân viên nhặt được đồng hồ đắt tiền khách bỏ quên và đề nghị giữ lại vì khách đã bay. Cách xử lý đúng là gì?",en:"An attendant finds an expensive watch a guest left behind and suggests keeping it as the guest has flown. What is correct?"},options:{vi:["Cho nhân viên giữ","Bán và chia cho cả ca","Ghi sổ đồ thất lạc, niêm phong, cất giữ và liên hệ trả khách","Để lại trong phòng"],en:["Let the attendant keep it","Sell it and share with the shift","Log it as lost property, seal, store it and contact the guest","Leave it in the room"]},answer:2,explain:{vi:"Đồ thất lạc phải ghi sổ, bảo quản an toàn và hoàn trả theo quy trình; giữ lại là chiếm đoạt tài sản.",en:"Lost property must be logged, stored safely and returned per procedure; keeping it is misappropriation."}}]}},"KK-798":{scenario:{company:"Công ty Tổ chức Sự kiện Bình Minh Xanh",supervisor:{name:"Quách Gia Bảo",role:{vi:"Trưởng dự án Sự kiện",en:"Event Project Lead"}},ref_code:"EV-7720",title:{vi:"Đúng sơ đồ phòng. Đúng hợp đồng. An toàn phòng cháy.",en:"Right room set. Right contract. Fire safety first."},brief:{vi:"Bạn rà soát hồ sơ hội nghị khách hàng EV-7720 tại một khách sạn: phiên chiều là hội thảo có thảo luận nhóm 8 người mỗi bàn tròn, mọi người cùng nhìn lên sân khấu. Hợp đồng khối phòng cam kết 120 đêm phòng, cho phép hụt 20% không phạt, giá hợp đồng 2.400.000 đồng/đêm; thực tế khách dùng 82 đêm phòng (số liệu mô phỏng). Sửa kiểu bố trí phòng và phí bồi thường khối phòng, rồi lập báo cáo có căn cứ.",en:"You are reviewing client conference file EV-7720 at a hotel: the afternoon session is a workshop with group discussions of 8 people per round table, everyone facing the stage. The room block contract commits 120 room nights, allows 20% attrition without penalty, at 2,400,000 VND per night; actual use was 82 room nights (training figures). Correct the room setup and the room block attrition charge, then write an evidence-based report."},reference_title:{vi:"Kịch bản chương trình & hợp đồng khối phòng đã duyệt · EV-7720",en:"Approved programme & room block contract · EV-7720"},fields:[{id:"ROOM_SETUP",label:{vi:"Kiểu bố trí phòng phiên chiều",en:"Afternoon room setup"},initial:"Theater",expected:"Cabaret",choices:["Theater","Classroom","Cabaret"],reference:"Bảng chọn kiểu bố trí theo hình thức phiên",hint:{vi:"Phiên thảo luận nhóm cần bàn tròn, đồng thời người ngồi phải nhìn được sân khấu mà không quay lưng lại.",en:"Group discussion needs round tables, and every seat must face the stage without turning away."}},{id:"ATTRITION",label:{vi:"Phí bồi thường khối phòng (VND)",en:"Room block attrition charge (VND)"},initial:"91200000",expected:"33600000",reference:"Hợp đồng khối phòng đã ký",ref_value:{vi:"Cam kết 120 đêm; cho phép hụt 20%; thực tế 82 đêm; giá 2.400.000 đồng/đêm (mô phỏng)",en:"Commitment 120 nights; 20% attrition allowed; actual 82 nights; 2,400,000 VND per night (training)"},hint:{vi:"Chỉ phần hụt vượt quá mức cho phép mới bị tính phí, không phải toàn bộ số đêm chưa dùng.",en:"Only the shortfall beyond the allowed attrition is charged, not all unused nights."}}],sop32:{vi:"Phí bồi thường = (số đêm cam kết x (1 - tỷ lệ hụt cho phép) - số đêm thực tế) x giá hợp đồng; nếu thực tế đạt mức tối thiểu thì phí bằng 0 (điều khoản mô phỏng).",en:"Attrition charge = (committed nights x (1 - allowed attrition) - actual nights) x contract rate; if actual use reaches the minimum, the charge is zero (training clause)."},context:{label:"EVENT FILE / EV-7720",metrics:[{label:{vi:"Đêm phòng cam kết",en:"Committed room nights"},value:"120"},{label:{vi:"Hụt cho phép",en:"Allowed attrition"},value:"20%"},{label:{vi:"Đêm phòng thực tế",en:"Actual room nights"},value:"82"}]},crisis:{vi:"Đạo diễn sân khấu muốn đặt backdrop và thùng thiết bị chắn cửa thoát hiểm phía sau, kê thêm 30 ghế vượt sức chứa được duyệt của phòng: “Khách hàng muốn đông, khách sạn không kiểm tra đâu.”",en:"The stage director wants to place the backdrop and equipment cases across the rear fire exit and add 30 chairs beyond the room's approved capacity: “The client wants it packed, the hotel won't check.”"},options:{safe:{vi:"Không chắn lối thoát hiểm, giữ đúng sức chứa được duyệt; báo trưởng dự án và bộ phận an ninh khách sạn, đề xuất bố trí lại sân khấu hoặc phòng phụ có truyền hình trực tiếp.",en:"Keep the fire exit clear and the approved capacity; inform the project lead and hotel security, and propose a new stage layout or an overflow room with a live feed."},shortcut:{vi:"Cho đặt backdrop chắn cửa và kê thêm ghế, dỡ ra ngay sau khi sự kiện kết thúc.",en:"Allow the backdrop across the exit and the extra chairs, then clear them right after the event."},wait:{vi:"Để đạo diễn và khách sạn tự thỏa thuận, mình chỉ lo phần đón khách.",en:"Let the director and the hotel sort it out while you handle registration only."}},questions:{vi:["Vì sao bạn đổi kiểu bố trí phòng phiên chiều? Yêu cầu nào của chương trình chứng minh lựa chọn đó?","Trình bày cách tính phí bồi thường khối phòng và cách xử lý khi phương án sân khấu vi phạm an toàn phòng cháy."],en:["Why did you change the afternoon room setup? Which programme requirement supports your choice?","Explain how you calculated the attrition charge and how you handle a stage plan that breaches fire safety."]},hints:{vi:["Đọc mô tả hình thức phiên trong kịch bản chương trình rồi đối chiếu với bảng chọn kiểu bố trí.","Theo SOP mục 3.2: tính mức tối thiểu sau khi trừ tỷ lệ hụt cho phép, rồi mới so với số đêm thực tế.","Đọc lại SOP mục 4.2: lối thoát nạn và sức chứa được duyệt không được thay đổi theo yêu cầu thẩm mỹ."],en:["Read the session format in the programme and compare it with the room setup table.","Per SOP 3.2: compute the minimum after allowed attrition, then compare it with actual nights.","Re-read SOP 4.2: escape routes and approved capacity cannot change for aesthetic reasons."]}},learning:{summary:{vi:"Chuyên viên tổ chức sự kiện MICE lên kế hoạch và vận hành hội nghị, hội thảo, chương trình khen thưởng và triển lãm: chọn địa điểm, đàm phán hợp đồng khách sạn, khối phòng, suất ăn, sân khấu âm thanh ánh sáng, đăng ký đại biểu, vận chuyển và kịch bản chương trình. Mục tiêu là sự kiện đạt mục tiêu của khách hàng, đúng ngân sách và an toàn tuyệt đối. Nghề đòi hỏi kỹ năng quản lý dự án, đọc hợp đồng, tính toán chi phí và giữ vững tiêu chuẩn an toàn trước áp lực khách hàng.",en:"A MICE event coordinator plans and runs meetings, incentives, conferences and exhibitions: choosing venues, negotiating hotel contracts, room blocks, catering, staging and AV, delegate registration, transport and the run of show. The goal is an event that meets the client's objectives, stays on budget and is completely safe. The role needs project management, contract reading, cost control and the firmness to keep safety standards under client pressure."},responsibilities:{vi:["Khảo sát, đề xuất địa điểm và kiểu bố trí phòng theo mục tiêu, hình thức từng phiên.","Đàm phán, theo dõi hợp đồng khách sạn: khối phòng, ngày chốt, tỷ lệ hụt, cam kết suất ăn.","Lập ngân sách, kiểm soát chi phí nhà cung cấp và quyết toán sau sự kiện.","Xây dựng kịch bản chương trình, điều phối sân khấu, âm thanh, ánh sáng và đăng ký đại biểu.","Lập kế hoạch an toàn, phòng cháy, y tế, sơ tán và xử lý sự cố tại hiện trường."],en:["Scout venues and propose room setups to fit each session's goals and format.","Negotiate and track hotel contracts: room blocks, cut-off dates, attrition and catering guarantees.","Build the budget, control supplier costs and settle accounts after the event.","Write the run of show and coordinate staging, sound, lighting and registration.","Plan safety, fire protection, medical support, evacuation and on-site incident response."]},competencies:[{name:{vi:"Quản lý dự án sự kiện",en:"Event project management"},desc:{vi:"Lập tiến độ ngược từ ngày sự kiện, phân công rõ và kiểm soát mốc quan trọng.",en:"Plan backwards from event day, assign clearly and control key milestones."}},{name:{vi:"Đọc và kiểm soát hợp đồng",en:"Contract control"},desc:{vi:"Hiểu điều khoản khối phòng, tỷ lệ hụt, hủy, cam kết suất ăn và tính đúng nghĩa vụ tài chính.",en:"Understand room block, attrition, cancellation and guarantee clauses and compute liabilities correctly."}},{name:{vi:"Thiết kế không gian",en:"Space design"},desc:{vi:"Chọn kiểu bố trí phù hợp hình thức phiên, tính sức chứa và lưu thông an toàn.",en:"Choose setups that fit the session format and plan capacity and safe circulation."}},{name:{vi:"Điều phối nhà cung cấp",en:"Supplier coordination"},desc:{vi:"Làm việc với khách sạn, sân khấu, vận chuyển, in ấn theo một kịch bản thống nhất.",en:"Work with hotels, staging, transport and print suppliers to one shared run of show."}},{name:{vi:"An toàn & liêm chính",en:"Safety & integrity"},desc:{vi:"Giữ lối thoát nạn, sức chứa được duyệt, báo cáo minh bạch và từ chối chi phí khống.",en:"Keep escape routes and approved capacity, report transparently and refuse fictitious costs."}}],knowledge:{vi:["Điều khoản hợp đồng MICE: khối phòng, ngày chốt (cut-off), tỷ lệ hụt cho phép (attrition), cam kết suất ăn (guarantee).","Luật Phòng cháy, chữa cháy và cứu nạn, cứu hộ năm 2024: lối thoát nạn và sức chứa tại nơi tập trung đông người.","Quy định về tổ chức hội nghị, hội thảo có yếu tố nước ngoài tại Việt Nam: xin phép cơ quan có thẩm quyền khi thuộc diện phải xin phép.","ISO 20121 về hệ thống quản lý sự kiện bền vững.","Kiểu bố trí phòng theater, classroom, cabaret, banquet, U-shape và định mức diện tích mỗi người.","Quản lý rủi ro sự kiện: phương án dự phòng thời tiết, y tế, an ninh và sơ tán."],en:["MICE contract terms: room blocks, cut-off dates, allowed attrition and catering guarantees.","Law on Fire Prevention, Firefighting and Rescue of 2024: escape routes and capacity in crowded venues.","Vietnamese rules on international conferences and seminars: obtain approval from the competent authority where required.","ISO 20121 on event sustainability management systems.","Theater, classroom, cabaret, banquet and U-shape setups and space per person.","Event risk management: contingency plans for weather, medical, security and evacuation."]},tools:["Phần mềm quản lý sự kiện và đăng ký đại biểu","Phần mềm vẽ sơ đồ mặt bằng sự kiện","Bảng ngân sách và quyết toán sự kiện","Kịch bản chương trình chi tiết","Ứng dụng check-in bằng mã QR"],kpis:{vi:["Điểm hài lòng của khách hàng và đại biểu sau sự kiện.","Chênh lệch chi phí thực tế so với ngân sách được duyệt.","Tỷ lệ đại biểu đăng ký có mặt thực tế.","Số sự cố an toàn và kỹ thuật trong sự kiện (mục tiêu bằng 0)."],en:["Client and delegate satisfaction after the event.","Actual cost variance against the approved budget.","Share of registered delegates who attend.","Safety and technical incidents during the event (target zero)."]},day:[{time:"08:00",vi:"Rà soát phiếu yêu cầu dịch vụ tiệc (BEO) và danh sách đại biểu cập nhật.",en:"Review the banquet event orders (BEO) and the updated delegate list."},{time:"10:00",vi:"Khảo sát địa điểm cùng khách sạn: sơ đồ phòng, lối thoát nạn, điểm đặt sân khấu.",en:"Walk the venue with the hotel: floor plan, escape routes and stage position."},{time:"13:30",vi:"Họp nhà cung cấp sân khấu, âm thanh, ánh sáng và chốt kịch bản chương trình.",en:"Meet staging, sound and lighting suppliers and lock the run of show."},{time:"15:30",vi:"Theo dõi số đêm phòng đã đặt so với cam kết trước ngày chốt khối phòng.",en:"Track room block pickup against the commitment before the cut-off date."},{time:"18:00",vi:"Tổng duyệt chương trình, kiểm tra an toàn hiện trường và bàn giao ca trực.",en:"Run the rehearsal, check on-site safety and hand over the duty shift."}],mistakes:{vi:["Chọn kiểu bố trí theo thói quen thay vì theo hình thức và mục tiêu của từng phiên.","Tính phí bồi thường trên toàn bộ số đêm chưa dùng, bỏ qua tỷ lệ hụt cho phép.","Chấp nhận chắn lối thoát hiểm hoặc vượt sức chứa để chiều ý khách hàng."],en:["Choosing a setup out of habit instead of each session's format and goal.","Charging attrition on all unused nights and ignoring the allowed percentage.","Accepting blocked exits or overcapacity to please the client."]},career:[{vi:"Trợ lý tổ chức sự kiện",en:"Event assistant"},{vi:"Chuyên viên tổ chức sự kiện MICE",en:"MICE event coordinator"},{vi:"Trưởng dự án sự kiện",en:"Event project lead"},{vi:"Giám đốc MICE và sự kiện",en:"Director of MICE and events"}],glossary:[{term:"MICE",vi:"Loại hình du lịch kết hợp hội họp, khen thưởng, hội nghị và triển lãm.",en:"Meetings, incentives, conferences and exhibitions as a travel segment."},{term:"Attrition",vi:"Tỷ lệ hụt cho phép so với số đêm phòng cam kết trước khi bị tính phí bồi thường.",en:"Allowed shortfall against committed room nights before a penalty applies."},{term:"Cut-off date",vi:"Ngày chốt khối phòng; sau ngày này phòng chưa đặt được trả lại cho khách sạn.",en:"Room block deadline after which unbooked rooms return to the hotel."},{term:"BEO",vi:"Phiếu yêu cầu dịch vụ tiệc ghi chi tiết bố trí phòng, thực đơn, thiết bị và thời gian.",en:"Banquet event order detailing room setup, menu, equipment and timing."},{term:"Cabaret setup",vi:"Kiểu bố trí bàn tròn chỉ xếp ghế ở phần bàn hướng về sân khấu, phù hợp thảo luận nhóm.",en:"Round tables seated only on the side facing the stage, suited to group work."}],quiz:[{q:{vi:"Hợp đồng cam kết 200 đêm phòng, cho phép hụt 10%, giá 2.000.000 đồng/đêm; thực tế dùng 170 đêm. Phí bồi thường là bao nhiêu?",en:"A contract commits 200 room nights with 10% attrition at 2,000,000 VND per night; actual use is 170 nights. What is the charge?"},options:{vi:["60.000.000 đồng","40.000.000 đồng","0 đồng","20.000.000 đồng"],en:["60,000,000 VND","40,000,000 VND","0 VND","20,000,000 VND"]},answer:3,explain:{vi:"Mức tối thiểu = 200 x 90% = 180 đêm; hụt vượt mức = 180 - 170 = 10 đêm; phí = 10 x 2.000.000 = 20.000.000 đồng.",en:"Minimum = 200 x 90% = 180 nights; excess shortfall = 180 - 170 = 10 nights; charge = 10 x 2,000,000 = 20,000,000 VND."}},{q:{vi:"Cut-off date trong hợp đồng khối phòng là gì?",en:"What is the cut-off date in a room block contract?"},options:{vi:["Ngày khai mạc sự kiện","Ngày thanh toán cuối cùng","Ngày chốt, sau đó phòng chưa đặt được trả lại khách sạn","Ngày khách sạn gửi hóa đơn"],en:["Event opening day","Final payment date","Deadline after which unbooked rooms return to the hotel","Date the hotel sends the invoice"]},answer:2,explain:{vi:"Sau ngày chốt, khách sạn được bán phòng chưa đặt cho khách khác và điều khoản hụt bắt đầu được tính.",en:"After the cut-off, the hotel may resell unbooked rooms and the attrition terms start to apply."}},{q:{vi:"Khách hàng muốn đặt backdrop chắn một cửa thoát hiểm cho đẹp sân khấu. Bạn làm gì?",en:"The client wants a backdrop placed across a fire exit for a better stage look. What do you do?"},options:{vi:["Từ chối, giữ lối thoát nạn thông thoáng và đề xuất phương án sân khấu khác","Đồng ý nếu có người đứng canh cửa","Đồng ý trong giờ khai mạc","Hỏi ý kiến đại biểu"],en:["Refuse, keep the escape route clear and propose another stage design","Agree if someone guards the door","Agree only for the opening","Ask the delegates"]},answer:0,explain:{vi:"Lối thoát nạn phải luôn thông thoáng khi có người trong phòng; không có ngoại lệ vì lý do thẩm mỹ.",en:"Escape routes must stay clear whenever people are inside; there is no exception for aesthetics."}},{q:{vi:"Phiên đào tạo cần học viên ghi chép, dùng máy tính và nhìn lên màn hình chiếu. Kiểu bố trí phù hợp nhất là gì?",en:"A training session needs note-taking, laptops and a view of the screen. Which setup fits best?"},options:{vi:["Theater","Classroom","Banquet","Cocktail"],en:["Theater","Classroom","Banquet","Cocktail"]},answer:1,explain:{vi:"Classroom có hàng bàn hướng về màn hình, đủ mặt bàn để ghi chép và đặt máy tính.",en:"Classroom uses rows of tables facing the screen with room for notes and laptops."}}]}},"KK-799":{scenario:{company:"Mây Ngàn Hospitality",supervisor:{name:"Trần Minh Khôi",role:{vi:"Giám đốc Ẩm thực",en:"Director of Food & Beverage"}},ref_code:"BEO-4417",title:{vi:"Đúng định lượng. Đúng dị ứng. Đúng an toàn thực phẩm.",en:"Right yield. Right allergens. Right food safety."},brief:{vi:"Tiệc cưới BEO-4417 tối nay có 240 khách. Món chính là thăn bò áp chảo, định lượng 180 g thịt đã sơ chế mỗi suất; tỷ lệ thu hồi thăn bò sau khi lọc gân mỡ là 75% (số liệu mô phỏng). Khai vị là gỏi ngó sen tôm rắc đậu phộng rang. Đối chiếu phiếu BEO nháp với thẻ công thức chuẩn, sửa khai báo chất gây dị ứng của món khai vị và lượng thăn bò cần đặt mua (kg), rồi lập báo cáo có căn cứ.",en:"Wedding banquet BEO-4417 tonight has 240 guests. The main course is pan-seared beef tenderloin, 180 g of trimmed meat per portion; the tenderloin yield after trimming is 75% (training data). The starter is lotus stem salad with shrimp and roasted peanuts. Compare the draft BEO with the standard recipe cards, correct the starter allergen declaration and the tenderloin purchase quantity (kg), then write an evidence-based report."},reference_title:{vi:"Thẻ công thức chuẩn & bảng định lượng đã duyệt · BEO-4417",en:"Approved standard recipe cards & yield sheet · BEO-4417"},fields:[{id:"ALLERGEN",label:{vi:"Khai báo dị ứng món khai vị",en:"Starter allergen declaration"},initial:"NONE",expected:"PEANUT+CRUSTACEAN",choices:["NONE","GLUTEN","PEANUT+CRUSTACEAN"],reference:"Thẻ công thức gỏi ngó sen",hint:{vi:"Liệt kê mọi nguyên liệu trong công thức, kể cả phần rắc trang trí và nước sốt, rồi đối chiếu danh mục chất gây dị ứng chính.",en:"List every ingredient in the recipe, including garnish and dressing, then check them against the major allergen list."}},{id:"BEEF_AP_KG",label:{vi:"Lượng thăn bò cần đặt mua (kg)",en:"Tenderloin to purchase (kg)"},initial:"43.2",expected:"57.6",reference:"Bảng định lượng món chính",ref_value:{vi:"240 suất x 180 g thịt đã sơ chế; tỷ lệ thu hồi thăn bò 75%",en:"240 portions x 180 g trimmed meat; tenderloin yield 75%"},hint:{vi:"Định lượng trên đĩa là khối lượng đã sơ chế (EP); hàng mua về là khối lượng nguyên trạng (AP).",en:"The plated weight is edible portion (EP); goods are bought as purchased (AP)."}}],sop32:{vi:"Lượng đặt mua (AP) = số suất x định lượng thành phẩm đã sơ chế (EP) / tỷ lệ thu hồi; đổi gam sang kg và làm tròn 1 chữ số thập phân.",en:"Purchase quantity (AP) = portions x edible portion weight (EP) / yield percentage; convert grams to kg and round to 1 decimal place."},context:{label:"BEO NHÁP / BEO-4417",metrics:[{label:{vi:"Số khách",en:"Guests"},value:"240"},{label:{vi:"Định lượng EP",en:"EP portion"},value:"180 g"},{label:{vi:"Tỷ lệ thu hồi mô phỏng",en:"Training yield"},value:"75%"}]},crisis:{vi:"Thủ kho báo 6 kg kem tươi đã hết hạn từ hôm qua. Quản lý nhà hàng nhắn: “Dán nhãn ngày mới rồi dùng cho món tráng miệng tối nay, nhà cung cấp mai mới giao, khách không biết đâu.”",en:"The storekeeper reports 6 kg of fresh cream expired yesterday. The restaurant manager texts: “Put a new date label on it and use it for tonight's dessert, the supplier only delivers tomorrow and guests will never know.”"},options:{safe:{vi:"Từ chối dán lại nhãn, cô lập và hủy kem theo quy trình có biên bản, báo Giám đốc Ẩm thực; đổi món tráng miệng hoặc mua gấp từ nhà cung cấp đã phê duyệt.",en:"Refuse to relabel, quarantine and discard the cream with a record, inform the F&B Director; switch the dessert or buy urgently from an approved supplier."},shortcut:{vi:"Dán nhãn ngày mới và dùng kem vì chỉ quá hạn một ngày, nếu có vấn đề thì xử lý sau.",en:"Relabel and use the cream since it is only one day past date, deal with any issue later."},wait:{vi:"Để nguyên kem trong kho và chờ quản lý nhà hàng tự quyết định.",en:"Leave the cream in storage and wait for the restaurant manager to decide."}},questions:{vi:["Vì sao khai báo PEANUT+CRUSTACEAN thay vì NONE? Thẻ công thức nào chứng minh điều đó?","Trình bày cách tính 57.6 kg thăn bò và rủi ro vận hành nếu đặt hàng theo khối lượng đã sơ chế."],en:["Why declare PEANUT+CRUSTACEAN instead of NONE? Which recipe card proves it?","Explain how you reached 57.6 kg of tenderloin and the operational risk of ordering by trimmed weight."]},hints:{vi:["Đặt phiếu BEO nháp cạnh thẻ công thức và đánh dấu từng nguyên liệu chứa chất gây dị ứng.","Áp dụng SOP mục 3.2: chia khối lượng thành phẩm cho tỷ lệ thu hồi trước khi đặt hàng.","Đọc lại SOP mục 4.2: thực phẩm quá hạn phải cô lập, hủy có biên bản và báo cáo, không được dán lại nhãn."],en:["Place the draft BEO next to the recipe card and flag each ingredient that contains an allergen.","Apply SOP 3.2: divide the finished weight by the yield before ordering.","Re-read SOP 4.2: expired food must be quarantined, discarded with a record and reported, never relabelled."]}},learning:{summary:{vi:"Bếp trưởng điều hành và quản lý bếp chịu trách nhiệm toàn bộ hoạt động bếp: xây dựng thực đơn và công thức chuẩn, kiểm soát giá vốn thực phẩm, lập kế hoạch sản xuất cho nhà hàng và tiệc, quản lý đội ngũ, thiết bị và bảo đảm an toàn thực phẩm theo HACCP. Vị trí đòi hỏi tay nghề vững, tư duy chi phí, khả năng điều phối dưới áp lực cao và kỷ luật vệ sinh tuyệt đối.",en:"An executive chef and kitchen manager runs the whole kitchen: designing menus and standard recipes, controlling food cost, planning production for restaurants and banquets, managing the team and equipment, and ensuring food safety under HACCP. The role requires strong culinary skills, cost thinking, coordination under heavy pressure and uncompromising hygiene discipline."},responsibilities:{vi:["Xây dựng thực đơn, thẻ công thức chuẩn và định lượng cho từng món, từng loại tiệc.","Lập kế hoạch sản xuất, đặt hàng theo tỷ lệ thu hồi và kiểm soát tồn kho theo FEFO.","Kiểm soát giá vốn thực phẩm, hao hụt và đối chiếu với ngân sách hằng tháng.","Vận hành hệ thống HACCP, kiểm thực ba bước, lưu mẫu thức ăn và hồ sơ nhiệt độ.","Tuyển chọn, phân ca, đào tạo đội bếp và giám sát chất lượng từng món ra pass."],en:["Build menus, standard recipe cards and portion specs for every dish and banquet type.","Plan production, order by yield percentages and control stock using FEFO.","Control food cost and waste and reconcile them with the monthly budget.","Run the HACCP system, three-step food checks, food sample retention and temperature logs.","Recruit, roster and train the kitchen brigade and check the quality of every plate at the pass."]},competencies:[{name:{vi:"Kế hoạch sản xuất & định lượng",en:"Production planning & yield"},desc:{vi:"Quy đổi số suất thành lượng nguyên liệu mua về dựa trên định lượng EP và tỷ lệ thu hồi thực tế.",en:"Convert portion counts into purchase quantities using EP specs and real yield percentages."}},{name:{vi:"Kiểm soát giá vốn",en:"Food cost control"},desc:{vi:"Tính giá thành từng món, theo dõi food cost %, giảm hao hụt và định giá bán hợp lý.",en:"Cost every dish, track food cost percentage, cut waste and set sound menu prices."}},{name:{vi:"An toàn thực phẩm & HACCP",en:"Food safety & HACCP"},desc:{vi:"Xác định điểm kiểm soát tới hạn, giới hạn nhiệt độ, thời gian và hành động khắc phục.",en:"Identify critical control points, temperature and time limits and corrective actions."}},{name:{vi:"Lãnh đạo đội bếp",en:"Kitchen leadership"},desc:{vi:"Phân công rõ ràng, giữ nhịp ra món giờ cao điểm và huấn luyện kỷ luật vệ sinh.",en:"Assign roles clearly, keep service pace at peak hours and coach hygiene discipline."}},{name:{vi:"Phát triển thực đơn",en:"Menu development"},desc:{vi:"Kết hợp sáng tạo với mùa vụ, nguồn cung, chi phí và yêu cầu ăn kiêng, dị ứng của khách.",en:"Blend creativity with seasonality, supply, cost and guests' dietary and allergy needs."}}],knowledge:{vi:["Luật An toàn thực phẩm số 55/2010/QH12 và Nghị định 15/2018/NĐ-CP hướng dẫn thi hành.","Bảy nguyên tắc HACCP theo Nguyên tắc chung về vệ sinh thực phẩm của Codex (CXC 1-1969) và hệ thống ISO 22000:2018.","Chế độ kiểm thực ba bước và lưu mẫu thức ăn tối thiểu 24 giờ theo hướng dẫn của Bộ Y tế (Quyết định 1246/QĐ-BYT năm 2017).","Vùng nhiệt độ nguy hiểm khoảng 5-60°C; làm nguội nhanh hai giai đoạn và giữ nóng, giữ lạnh đúng giới hạn.","Công thức giá vốn: food cost % = giá vốn nguyên liệu / doanh thu món; AP = EP / tỷ lệ thu hồi.","Danh mục 14 nhóm chất gây dị ứng chính theo Quy định (EU) 1169/2011, thường được khách sạn quốc tế áp dụng."],en:["Food Safety Law No. 55/2010/QH12 and its implementing Decree 15/2018/ND-CP.","The seven HACCP principles under the Codex General Principles of Food Hygiene (CXC 1-1969) and ISO 22000:2018.","Three-step food checks and food sample retention for at least 24 hours per Ministry of Health guidance (Decision 1246/QD-BYT, 2017).","Temperature danger zone of about 5-60°C; two-stage rapid cooling and correct hot and cold holding limits.","Cost formulas: food cost % = ingredient cost / dish revenue; AP = EP / yield percentage.","The 14 major allergen groups listed in Regulation (EU) 1169/2011, widely used by international hotels."]},tools:["Nhiệt kế đầu dò thực phẩm","Lò hấp nướng đa năng (combi oven)","Tủ làm lạnh nhanh (blast chiller)","Phần mềm quản lý kho và giá vốn bếp","Thẻ công thức chuẩn & bảng định lượng","Màn hình phiếu gọi món tại bếp (KDS)"],kpis:{vi:["Food cost % thực tế so với ngân sách (mục tiêu mô phỏng 28-32%).","Tỷ lệ hao hụt và thực phẩm phải hủy trên tổng giá trị nhập.","Điểm kiểm tra vệ sinh an toàn thực phẩm nội bộ và số sự cố ngộ độc (mục tiêu bằng 0).","Thời gian ra món trung bình và tỷ lệ món bị khách trả lại."],en:["Actual food cost % versus budget (training target 28-32%).","Waste and discarded food as a share of total purchases.","Internal food safety audit score and food poisoning incidents (target zero).","Average ticket time and share of dishes returned by guests."]},day:[{time:"07:00",vi:"Nhận hàng, đo nhiệt độ đầu dò, kiểm tra hạn dùng và từ chối lô không đạt.",en:"Receive goods, probe temperatures, check dates and reject failing batches."},{time:"09:30",vi:"Họp giao ca, phân công mise en place và chốt định lượng cho tiệc tối.",en:"Run the briefing, assign mise en place and confirm quantities for the evening banquet."},{time:"11:30",vi:"Kiểm thực, lưu mẫu và đứng pass giám sát giờ cao điểm bữa trưa.",en:"Do food checks, retain samples and run the pass during the lunch peak."},{time:"15:00",vi:"Tính giá vốn món mới, rà hao hụt tuần và đặt hàng ngày mai theo FEFO.",en:"Cost a new dish, review weekly waste and place tomorrow's orders using FEFO."},{time:"18:00",vi:"Điều phối ra món tiệc, kiểm tra đĩa mẫu và ghi hồ sơ nhiệt độ cuối ngày.",en:"Coordinate banquet service, check the sample plate and complete end-of-day temperature logs."}],mistakes:{vi:["Đặt hàng theo khối lượng đã sơ chế mà quên chia tỷ lệ thu hồi, dẫn tới thiếu món giữa tiệc.","Sao chép thẻ công thức cũ, bỏ sót nguyên liệu gây dị ứng ở phần rắc trang trí hoặc nước sốt.","Dán lại nhãn thực phẩm quá hạn để tiết kiệm chi phí, gây nguy cơ ngộ độc và vi phạm pháp luật."],en:["Ordering by trimmed weight without dividing by yield, causing shortages mid-banquet.","Copying an old recipe card and missing allergens in the garnish or dressing.","Relabelling expired food to save cost, risking food poisoning and breaking the law."]},career:[{vi:"Đầu bếp phụ trách khu vực (Chef de partie)",en:"Chef de partie"},{vi:"Bếp phó (Sous chef)",en:"Sous chef"},{vi:"Bếp trưởng (Head chef)",en:"Head chef"},{vi:"Bếp trưởng điều hành & Quản lý ẩm thực",en:"Executive chef & culinary director"}],glossary:[{term:"Yield",vi:"Tỷ lệ thu hồi: phần trăm khối lượng dùng được sau sơ chế so với khối lượng mua về.",en:"Usable weight after trimming as a percentage of the as-purchased weight."},{term:"EP / AP",vi:"Khối lượng đã sơ chế dùng được (EP) và khối lượng nguyên trạng khi mua (AP).",en:"Edible portion weight (EP) and as-purchased weight (AP)."},{term:"CCP",vi:"Điểm kiểm soát tới hạn trong HACCP, nơi phải kiểm soát để loại bỏ hoặc giảm mối nguy.",en:"Critical control point in HACCP where control is essential to remove or reduce a hazard."},{term:"FEFO",vi:"Hết hạn trước xuất trước: ưu tiên dùng lô có hạn sử dụng gần nhất.",en:"First expired, first out: use the batch with the nearest expiry date first."},{term:"BEO",vi:"Phiếu sự kiện tiệc ghi thực đơn, số khách, giờ phục vụ và yêu cầu đặc biệt.",en:"Banquet event order listing menu, guest count, service times and special requests."}],quiz:[{q:{vi:"Món bán giá 250.000 VND, giá vốn nguyên liệu 80.000 VND. Food cost % là bao nhiêu?",en:"A dish sells for 250,000 VND with an ingredient cost of 80,000 VND. What is the food cost %?"},options:{vi:["24%","28%","32%","36%"],en:["24%","28%","32%","36%"]},answer:2,explain:{vi:"Food cost % = 80.000 / 250.000 = 0,32, tức 32%.",en:"Food cost % = 80,000 / 250,000 = 0.32, that is 32%."}},{q:{vi:"Vùng nhiệt độ nguy hiểm cho vi sinh vật phát triển trong thực phẩm là khoảng nào?",en:"What is the temperature danger zone for bacterial growth in food?"},options:{vi:["Khoảng 5-60°C","Dưới 0°C","Trên 75°C","Khoảng 60-100°C"],en:["About 5-60°C","Below 0°C","Above 75°C","About 60-100°C"]},answer:0,explain:{vi:"Vi khuẩn sinh sôi nhanh trong khoảng 5-60°C nên phải giữ lạnh dưới 5°C hoặc giữ nóng trên 60°C.",en:"Bacteria multiply quickly between 5 and 60°C, so hold food cold below 5°C or hot above 60°C."}},{q:{vi:"Nguyên tắc FEFO trong quản lý kho bếp nghĩa là gì?",en:"What does FEFO mean in kitchen stock control?"},options:{vi:["Nhập trước xuất trước","Lô hết hạn trước được xuất dùng trước","Lô đắt tiền dùng trước","Lô mới nhập dùng trước"],en:["First in, first out","The batch expiring first is used first","The most expensive batch is used first","The newest batch is used first"]},answer:1,explain:{vi:"FEFO ưu tiên lô có hạn dùng gần nhất, giảm hủy bỏ và rủi ro dùng hàng quá hạn.",en:"FEFO prioritizes the batch with the nearest expiry, reducing waste and the risk of using expired goods."}},{q:{vi:"Quản lý yêu cầu dán lại nhãn cho kem tươi quá hạn để dùng cho tiệc. Bạn làm gì?",en:"A manager asks you to relabel expired cream for a banquet. What do you do?"},options:{vi:["Dán lại nhãn vì chỉ quá hạn một ngày","Nếm thử, nếu còn ngon thì dùng","Chờ quản lý tự xử lý","Từ chối, hủy có biên bản, báo cáo và đổi phương án món"],en:["Relabel it since it is only one day over","Taste it and use it if it seems fine","Wait for the manager to handle it","Refuse, discard with a record, report and change the dish plan"]},answer:3,explain:{vi:"Dán lại nhãn thực phẩm quá hạn là vi phạm an toàn thực phẩm; phải hủy có kiểm soát và tìm phương án hợp lệ.",en:"Relabelling expired food breaches food safety rules; discard it under control and find a compliant alternative."}}]}},"KK-800":{scenario:{company:"Cẩm Thạch Bay Resort",supervisor:{name:"Lê Hoàng Yến",role:{vi:"Giám đốc Trải nghiệm Khách hàng",en:"Director of Guest Experience"}},ref_code:"LYL-5308",title:{vi:"Đúng hạng hội viên. Đúng điểm thưởng. Đúng cam kết.",en:"Right tier. Right points. Right promise."},brief:{vi:"Hội viên mã LYL-5308 vừa trả phòng sau 3 đêm, giá phòng 2.400.000 VND/đêm chưa gồm phí dịch vụ và VAT (số liệu mô phỏng). Hồ sơ ghi 32 đêm đủ điều kiện trong 12 tháng gần nhất; ngưỡng hạng mô phỏng: Silver từ 10 đêm, Gold từ 25 đêm, Platinum từ 50 đêm. Đối chiếu bản ghi nháp với quy chế chương trình thành viên, sửa hạng hội viên và số điểm được cộng cho kỳ lưu trú, rồi lập báo cáo có căn cứ.",en:"Member LYL-5308 has just checked out after 3 nights at 2,400,000 VND per night before service charge and VAT (training data). The profile shows 32 qualifying nights in the last 12 months; training tier thresholds: Silver from 10 nights, Gold from 25 nights, Platinum from 50 nights. Compare the draft record with the loyalty program rules, correct the member tier and the points earned for the stay, then write an evidence-based report."},reference_title:{vi:"Quy chế chương trình thành viên đã duyệt · LYL-5308",en:"Approved loyalty program rules · LYL-5308"},fields:[{id:"TIER",label:{vi:"Hạng hội viên",en:"Member tier"},initial:"SILVER",expected:"GOLD",choices:["SILVER","GOLD","PLATINUM"],reference:"Bảng tiêu chí xét hạng",hint:{vi:"Đếm số đêm đủ điều kiện trong 12 tháng cuộn gần nhất, không chỉ trong năm dương lịch hiện tại.",en:"Count qualifying nights over the rolling last 12 months, not only the current calendar year."}},{id:"POINTS",label:{vi:"Điểm thưởng kỳ lưu trú",en:"Points earned for the stay"},initial:"792",expected:"900",reference:"Bảng tính điểm kỳ lưu trú",ref_value:{vi:"Doanh thu phòng trước phí dịch vụ và VAT: 3 đêm x 2.400.000 VND",en:"Room revenue before service charge and VAT: 3 nights x 2,400,000 VND"},hint:{vi:"Tính điểm cơ bản trước, sau đó áp dụng tỷ lệ thưởng đúng với hạng đã được xác định lại.",en:"Compute base points first, then apply the bonus rate of the corrected tier."}}],sop32:{vi:"Điểm cơ bản = 10 điểm cho mỗi 100.000 VND doanh thu phòng trước phí dịch vụ và VAT; điểm thưởng theo hạng: Silver +10%, Gold +25%, Platinum +50% (số liệu mô phỏng).",en:"Base points = 10 points per 100,000 VND of room revenue before service charge and VAT; tier bonus: Silver +10%, Gold +25%, Platinum +50% (training data)."},context:{label:"CRM HỘI VIÊN / LYL-5308",metrics:[{label:{vi:"Đêm đủ điều kiện 12 tháng",en:"Qualifying nights, 12 months"},value:"32"},{label:{vi:"Số đêm kỳ này",en:"Nights this stay"},value:"3"},{label:{vi:"Giá phòng mô phỏng",en:"Training room rate"},value:"2,400,000 VND"}]},crisis:{vi:"Khách dọa đăng đánh giá 1 sao vì máy lạnh hỏng một đêm. Trưởng ca nói: “Tặng thêm 5.000 điểm ngoài quy chế, điều kiện là khách xóa đánh giá cũ và viết 5 sao. Không cần ghi vào luồng phê duyệt.”",en:"A guest threatens a 1-star review because the air conditioning failed one night. The shift leader says: “Give 5,000 extra points outside the rules on condition the guest deletes the old review and posts 5 stars. No need to log it for approval.”"},options:{safe:{vi:"Từ chối đổi điểm lấy đánh giá; xin lỗi, bồi hoàn theo chính sách khắc phục dịch vụ có phê duyệt, ghi nhận trên hệ thống và báo Giám đốc Trải nghiệm Khách hàng.",en:"Refuse to trade points for reviews; apologize, compensate under the approved service recovery policy, log it in the system and inform the Director of Guest Experience."},shortcut:{vi:"Cộng 5.000 điểm ngoài quy chế để khách đổi đánh giá, coi như chi phí giữ uy tín.",en:"Add 5,000 off-policy points so the guest changes the review, treating it as a reputation cost."},wait:{vi:"Không phản hồi khách và chờ xem khách có thật sự đăng đánh giá hay không.",en:"Do not respond and wait to see whether the guest actually posts the review."}},questions:{vi:["Vì sao hội viên LYL-5308 thuộc hạng GOLD và được cộng 900 điểm? Trình bày từng bước tính.","Rủi ro pháp lý và uy tín nào phát sinh nếu tặng điểm để đổi lấy đánh giá tốt? Bạn xử lý khiếu nại thế nào?"],en:["Why is member LYL-5308 GOLD and earning 900 points? Show each calculation step.","What legal and reputational risks arise from giving points in exchange for good reviews? How do you handle the complaint?"]},hints:{vi:["Đặt bản ghi nháp cạnh bảng tiêu chí xét hạng và đếm lại số đêm theo 12 tháng cuộn.","Áp dụng SOP mục 3.2: tính trên doanh thu phòng chưa gồm phí dịch vụ và VAT, rồi mới cộng thưởng hạng.","Đọc lại SOP mục 4.2: mọi khoản bồi hoàn phải theo chính sách, có phê duyệt và không gắn điều kiện đánh giá."],en:["Place the draft record next to the tier criteria and recount nights over a rolling 12 months.","Apply SOP 3.2: use room revenue before service charge and VAT, then add the tier bonus.","Re-read SOP 4.2: every compensation must follow policy, be approved and never be tied to a review."]}},learning:{summary:{vi:"Chuyên viên quan hệ khách hàng và chương trình thành viên chăm sóc khách lưu trú, đặc biệt là khách quay lại và hội viên, quản lý hạng, điểm thưởng, quyền lợi và xử lý phàn nàn để biến trải nghiệm chưa tốt thành lòng trung thành. Công việc đòi hỏi kỹ năng giao tiếp tinh tế, đọc dữ liệu CRM chính xác, nắm chắc quy chế chương trình và giữ chuẩn mực trung thực, bảo vệ dữ liệu khách hàng.",en:"A guest relations and loyalty executive looks after in-house guests, especially returning guests and members, manages tiers, points, benefits and complaints, and turns weak experiences into loyalty. The role requires refined communication, accurate reading of CRM data, firm knowledge of program rules and strict standards of honesty and customer data protection."},responsibilities:{vi:["Đón tiếp khách hội viên, khách VIP và cá nhân hóa trải nghiệm dựa trên hồ sơ sở thích.","Quản lý ghi danh, xét hạng, cộng trừ điểm và quyền lợi theo đúng quy chế chương trình.","Tiếp nhận và xử lý phàn nàn theo quy trình khắc phục dịch vụ, theo dõi đến khi đóng hồ sơ.","Phân tích dữ liệu khảo sát, NPS và đánh giá trực tuyến để đề xuất cải tiến dịch vụ.","Bảo vệ dữ liệu cá nhân của khách, chỉ sử dụng đúng mục đích và theo sự đồng ý."],en:["Welcome members and VIP guests and personalize stays from preference profiles.","Manage enrollment, tier review, point credits and benefits strictly under program rules.","Receive and resolve complaints through the service recovery process until closure.","Analyze surveys, NPS and online reviews to propose service improvements.","Protect guests' personal data and use it only for agreed purposes with consent."]},competencies:[{name:{vi:"Giao tiếp & khắc phục dịch vụ",en:"Communication & service recovery"},desc:{vi:"Lắng nghe, xin lỗi chân thành, đưa giải pháp cụ thể và theo dõi đến khi khách hài lòng.",en:"Listen, apologize sincerely, offer concrete solutions and follow up until the guest is satisfied."}},{name:{vi:"Vận hành chương trình thành viên",en:"Loyalty program operations"},desc:{vi:"Áp dụng chính xác quy tắc xét hạng, tích điểm, hết hạn điểm và quyền lợi theo hạng.",en:"Apply tier, earning, expiry and benefit rules accurately for each level."}},{name:{vi:"Phân tích dữ liệu khách hàng",en:"Customer data analysis"},desc:{vi:"Đọc CRM, phân khúc khách, đo NPS và tỷ lệ quay lại để ra quyết định chăm sóc.",en:"Read CRM data, segment guests and measure NPS and repeat rates to guide care actions."}},{name:{vi:"Liêm chính & tuân thủ",en:"Integrity & compliance"},desc:{vi:"Không mua bán đánh giá, không cộng điểm ngoài quy chế và bảo vệ dữ liệu cá nhân của khách.",en:"Never buy reviews, never grant off-policy points and protect guests' personal data."}},{name:{vi:"Phối hợp liên bộ phận",en:"Cross-department coordination"},desc:{vi:"Làm việc với tiền sảnh, buồng phòng, kỹ thuật, ẩm thực để xử lý nhanh yêu cầu của khách.",en:"Work with front office, housekeeping, engineering and F&B to resolve guest requests quickly."}}],knowledge:{vi:["Luật Bảo vệ quyền lợi người tiêu dùng số 19/2023/QH15: thông tin trung thực, giải quyết khiếu nại của khách.","Quy định hiện hành về bảo vệ dữ liệu cá nhân: thu thập có đồng ý, đúng mục đích, bảo mật và cho phép khách rút lại đồng ý.","Mô hình đo lường trải nghiệm: NPS = % người ủng hộ (9-10) trừ % người phản đối (0-6).","Kế toán điểm thưởng theo IFRS 15: điểm là nghĩa vụ thực hiện riêng, phần doanh thu tương ứng được ghi nhận khi điểm được đổi hoặc hết hạn.","Nguyên tắc khắc phục dịch vụ: lắng nghe, đồng cảm, xin lỗi, giải quyết, cảm ơn và theo dõi."],en:["Consumer Rights Protection Law No. 19/2023/QH15: truthful information and handling consumer complaints.","Current personal data protection rules: consent-based, purpose-limited collection, security and the right to withdraw consent.","Experience measurement: NPS = % promoters (9-10) minus % detractors (0-6).","Loyalty points under IFRS 15: points are a separate performance obligation, with the related revenue recognized when points are redeemed or expire.","Service recovery principles: listen, empathize, apologize, resolve, thank and follow up."]},tools:["Hệ thống quản lý khách sạn (PMS)","Phần mềm CRM và chương trình thành viên","Công cụ khảo sát và đo NPS","Nền tảng theo dõi đánh giá trực tuyến","Sổ theo dõi phàn nàn và khắc phục dịch vụ","Microsoft Excel"],kpis:{vi:["Chỉ số NPS và điểm hài lòng của khách hội viên.","Tỷ lệ khách quay lại và tỷ lệ hội viên được giữ lại sau 12 tháng.","Thời gian phản hồi và tỷ lệ phàn nàn được đóng trong 24 giờ.","Số lỗi cộng điểm, xét hạng phát hiện khi kiểm tra (mục tiêu bằng 0)."],en:["NPS and member satisfaction scores.","Repeat guest rate and member retention after 12 months.","Response time and share of complaints closed within 24 hours.","Point and tier errors found in audits (target zero)."]},day:[{time:"08:00",vi:"Xem danh sách khách đến, hội viên hạng cao và chuẩn bị quà chào mừng theo sở thích.",en:"Review arrivals and high-tier members and prepare welcome amenities by preference."},{time:"10:00",vi:"Gọi điện hỏi thăm khách đang lưu trú và ghi nhận yêu cầu phát sinh.",en:"Make courtesy calls to in-house guests and log new requests."},{time:"13:30",vi:"Kiểm tra cộng điểm của khách trả phòng hôm qua và xử lý yêu cầu điều chỉnh.",en:"Audit points for yesterday's departures and process adjustment requests."},{time:"15:30",vi:"Họp nhanh với các bộ phận về phàn nàn trong ngày và hành động khắc phục.",en:"Hold a quick huddle with departments on today's complaints and recovery actions."},{time:"17:00",vi:"Phản hồi đánh giá trực tuyến, cập nhật báo cáo NPS và bàn giao ca.",en:"Reply to online reviews, update the NPS report and hand over to the next shift."}],mistakes:{vi:["Xét hạng theo năm dương lịch thay vì 12 tháng cuộn như quy chế, làm khách mất quyền lợi.","Tính điểm trên tổng hóa đơn gồm phí dịch vụ và VAT, hoặc quên cộng thưởng theo hạng.","Tặng điểm, quà để đổi lấy đánh giá tốt, vi phạm chính sách và làm sai lệch thông tin người tiêu dùng."],en:["Reviewing tiers by calendar year instead of the rolling 12 months set by the rules, costing guests their benefits.","Computing points on the full bill including service charge and VAT, or forgetting the tier bonus.","Giving points or gifts in exchange for good reviews, breaching policy and misleading consumers."]},career:[{vi:"Nhân viên quan hệ khách hàng",en:"Guest relations officer"},{vi:"Chuyên viên chương trình thành viên",en:"Loyalty program executive"},{vi:"Trưởng bộ phận quan hệ khách hàng",en:"Guest relations manager"},{vi:"Giám đốc trải nghiệm khách hàng & CRM",en:"Director of guest experience & CRM"}],glossary:[{term:"Tier",vi:"Hạng hội viên xác định theo số đêm hoặc chi tiêu đủ điều kiện trong kỳ xét hạng.",en:"Membership level based on qualifying nights or spend during the review period."},{term:"Qualifying night",vi:"Đêm lưu trú đủ điều kiện xét hạng theo quy chế, thường loại trừ một số giá đặc biệt.",en:"A stay night that counts toward tier status under the rules, often excluding some special rates."},{term:"NPS",vi:"Chỉ số khách hàng sẵn sàng giới thiệu, tính bằng % ủng hộ trừ % phản đối.",en:"Net Promoter Score, calculated as % promoters minus % detractors."},{term:"Service recovery",vi:"Quy trình khắc phục sự cố dịch vụ để lấy lại niềm tin của khách.",en:"The process of fixing a service failure to win back the guest's trust."},{term:"Breakage",vi:"Phần điểm thưởng dự kiến không bao giờ được khách đổi, dùng khi ước tính nghĩa vụ điểm.",en:"The share of points expected never to be redeemed, used when estimating the points liability."}],quiz:[{q:{vi:"Khảo sát 200 khách: 120 người chấm 9-10, 50 người chấm 7-8, 30 người chấm 0-6. NPS là bao nhiêu?",en:"A survey of 200 guests: 120 scored 9-10, 50 scored 7-8 and 30 scored 0-6. What is the NPS?"},options:{vi:["60","45","75","35"],en:["60","45","75","35"]},answer:1,explain:{vi:"Ủng hộ 60% trừ phản đối 15% được NPS = 45.",en:"60% promoters minus 15% detractors gives NPS = 45."}},{q:{vi:"Theo IFRS 15, điểm thưởng tặng kèm khi khách lưu trú được ghi nhận thế nào?",en:"Under IFRS 15, how are loyalty points granted with a stay accounted for?"},options:{vi:["Ghi toàn bộ doanh thu ngay khi trả phòng","Ghi vào chi phí quảng cáo","Là nghĩa vụ thực hiện riêng, ghi nhận doanh thu khi điểm được đổi hoặc hết hạn","Không cần ghi nhận"],en:["Recognize all revenue at checkout","Book as advertising expense","A separate performance obligation recognized when points are redeemed or expire","No accounting needed"]},answer:2,explain:{vi:"IFRS 15 phân bổ một phần giá giao dịch cho điểm và hoãn ghi nhận đến khi nghĩa vụ được thực hiện.",en:"IFRS 15 allocates part of the transaction price to points and defers it until the obligation is satisfied."}},{q:{vi:"Trưởng ca đề nghị tặng điểm ngoài quy chế để khách xóa đánh giá xấu. Cách xử lý đúng là gì?",en:"The shift leader proposes off-policy points if the guest deletes a bad review. What is right?"},options:{vi:["Từ chối, bồi hoàn theo chính sách có phê duyệt và báo cáo cấp trên","Đồng ý vì giữ được uy tín","Tặng điểm nhưng không ghi hệ thống","Phớt lờ khách"],en:["Refuse, compensate under approved policy and escalate","Agree to protect reputation","Give points without logging them","Ignore the guest"]},answer:0,explain:{vi:"Đổi lợi ích lấy đánh giá làm sai lệch thông tin người tiêu dùng; bồi hoàn phải minh bạch, đúng chính sách.",en:"Trading benefits for reviews misleads consumers; compensation must be transparent and within policy."}},{q:{vi:"Khách hội viên yêu cầu ngừng nhận thư tiếp thị và xóa dữ liệu sở thích. Bạn làm gì?",en:"A member asks to stop marketing emails and delete preference data. What do you do?"},options:{vi:["Giữ lại vì còn hữu ích","Chuyển cho bộ phận bán hàng dùng tiếp","Chỉ xóa khi khách gửi văn bản công chứng","Ghi nhận rút lại đồng ý và xử lý theo quy trình bảo vệ dữ liệu"],en:["Keep it because it is useful","Pass it to Sales to keep using","Delete only with a notarized letter","Record the consent withdrawal and process it under the data protection procedure"]},answer:3,explain:{vi:"Khách có quyền rút lại đồng ý; doanh nghiệp phải ngừng xử lý và xóa dữ liệu theo quy trình đã ban hành.",en:"Guests may withdraw consent; the business must stop processing and delete the data under its procedure."}}]}},"KK-801":{scenario:{company:"Lam Tuyền Wellness Retreat",supervisor:{name:"Đỗ Thu Hà",role:{vi:"Giám đốc Vận hành Khu nghỉ dưỡng",en:"Resort Operations Director"}},ref_code:"SPA-2715",title:{vi:"Đúng liệu trình. Đúng chỉ số. Đúng an toàn cho khách.",en:"Right treatment. Right metric. Right guest safety."},brief:{vi:"Đây là tình huống đào tạo. Bạn rà soát báo cáo tuần SPA-2715. Spa có 6 phòng trị liệu, mở 10 giờ/ngày, 7 ngày; tuần qua bán 294 giờ trị liệu, doanh thu trị liệu 147.000.000 VND (số liệu mô phỏng). Phiếu sàng lọc sức khỏe của một khách ghi đang mang thai 20 tuần nhưng lịch đặt là massage đá nóng. Đối chiếu bản nháp với quy trình đã duyệt, sửa liệu trình phù hợp và chỉ số RevPATH (VND), rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You are reviewing weekly report SPA-2715. The spa has 6 treatment rooms, open 10 hours a day, 7 days a week; last week it sold 294 treatment hours with treatment revenue of 147,000,000 VND (training data). One guest's health screening form shows she is 20 weeks pregnant, yet she is booked for a hot stone massage. Compare the draft with the approved procedures, correct the treatment and the RevPATH metric (VND), then write an evidence-based report."},reference_title:{vi:"Quy trình sàng lọc & bảng chỉ số vận hành đã duyệt · SPA-2715",en:"Approved screening procedure & operating metrics sheet · SPA-2715"},fields:[{id:"TREATMENT",label:{vi:"Liệu trình xếp cho khách mang thai",en:"Treatment booked for the pregnant guest"},initial:"HOT-STONE",expected:"PRENATAL",choices:["HOT-STONE","DEEP-TISSUE","PRENATAL"],reference:"Bảng chống chỉ định liệu trình",hint:{vi:"Đọc phiếu sàng lọc trước khi xác nhận lịch: thai kỳ là chống chỉ định với liệu pháp nhiệt cao và tác động sâu.",en:"Read the screening form before confirming: pregnancy contraindicates high-heat and deep-pressure therapies."}},{id:"REVPATH",label:{vi:"Doanh thu trên giờ trị liệu khả dụng (VND)",en:"Revenue per available treatment hour (VND)"},initial:"500000",expected:"350000",reference:"Bảng chỉ số vận hành tuần",ref_value:{vi:"6 phòng x 10 giờ/ngày x 7 ngày; doanh thu trị liệu 147.000.000 VND",en:"6 rooms x 10 hours/day x 7 days; treatment revenue 147,000,000 VND"},hint:{vi:"Mẫu số của RevPATH là toàn bộ giờ có thể bán, không phải số giờ đã bán.",en:"The RevPATH denominator is all sellable hours, not the hours actually sold."}}],sop32:{vi:"RevPATH = doanh thu trị liệu / tổng giờ trị liệu khả dụng; giờ khả dụng = số phòng trị liệu x giờ mở cửa mỗi ngày x số ngày mở cửa trong kỳ.",en:"RevPATH = treatment revenue / total available treatment hours; available hours = treatment rooms x opening hours per day x opening days in the period."},context:{label:"SPA PMS / SPA-2715",metrics:[{label:{vi:"Phòng trị liệu",en:"Treatment rooms"},value:"6"},{label:{vi:"Giờ trị liệu đã bán",en:"Treatment hours sold"},value:"294"},{label:{vi:"Doanh thu trị liệu tuần",en:"Weekly treatment revenue"},value:"147,000,000 VND"}]},crisis:{vi:"Khách VIP nhất quyết muốn massage đá nóng đúng gói đã mua. Trưởng ca nói: “Cho khách ký giấy miễn trách nhiệm rồi cứ làm, đổi gói là mất doanh thu. Kỹ thuật viên chưa có chứng chỉ massage bầu cũng được.”",en:"A VIP guest insists on the hot stone massage in her package. The shift leader says: “Have her sign a waiver and just do it, changing the package loses revenue. A therapist without prenatal certification is fine.”"},options:{safe:{vi:"Từ chối liệu trình chống chỉ định dù có giấy miễn trách nhiệm, giải thích tế nhị, đề xuất massage bầu do kỹ thuật viên có chứng chỉ thực hiện, ghi hồ sơ và báo Giám đốc Vận hành.",en:"Decline the contraindicated treatment even with a waiver, explain tactfully, offer prenatal massage by a certified therapist, record it and inform the Operations Director."},shortcut:{vi:"Cho khách ký giấy miễn trách nhiệm và làm massage đá nóng để giữ doanh thu.",en:"Have the guest sign a waiver and perform the hot stone massage to keep the revenue."},wait:{vi:"Để kỹ thuật viên tự quyết định khi khách vào phòng trị liệu.",en:"Let the therapist decide when the guest arrives in the treatment room."}},questions:{vi:["Vì sao chuyển sang PRENATAL và RevPATH đúng là 350000 VND? Trình bày căn cứ từ phiếu sàng lọc và cách tính.","Vì sao giấy miễn trách nhiệm không thay thế được sàng lọc chống chỉ định? Bạn bảo vệ khách và spa thế nào?"],en:["Why switch to PRENATAL, and why is the correct RevPATH 350000 VND? Show the screening evidence and the calculation.","Why can a waiver not replace contraindication screening? How do you protect both the guest and the spa?"]},hints:{vi:["Đặt lịch đặt nháp cạnh bảng chống chỉ định và khoanh dòng thai kỳ.","Áp dụng SOP mục 3.2: tính giờ khả dụng từ số phòng, giờ mở cửa và số ngày trước khi chia doanh thu.","Đọc lại SOP mục 4.2: liệu trình chống chỉ định không được thực hiện vì áp lực doanh thu; phải báo cáo người có thẩm quyền."],en:["Place the draft booking next to the contraindication table and circle the pregnancy line.","Apply SOP 3.2: compute available hours from rooms, opening hours and days before dividing revenue.","Re-read SOP 4.2: contraindicated treatments are never performed under revenue pressure; escalate to the person in charge."]}},learning:{summary:{vi:"Quản lý spa và chăm sóc sức khỏe điều hành toàn bộ khu trị liệu: thiết kế thực đơn liệu trình, sàng lọc chống chỉ định, quản lý kỹ thuật viên, lịch phòng, vệ sinh khử khuẩn, sản phẩm và doanh thu. Mục tiêu là trải nghiệm thư giãn an toàn, nhất quán và hiệu quả kinh doanh, dựa trên kỷ luật quy trình, hiểu biết giới hạn của dịch vụ không phải y khoa và kỹ năng tư vấn tận tâm.",en:"A spa and wellness manager runs the whole treatment area: designing the treatment menu, contraindication screening, managing therapists, room schedules, hygiene and disinfection, products and revenue. The goal is a safe, consistent, relaxing experience with sound business results, based on procedural discipline, awareness of the limits of non-medical services and caring advisory skills."},responsibilities:{vi:["Xây dựng thực đơn liệu trình, quy trình chuẩn từng dịch vụ và bộ phiếu sàng lọc sức khỏe.","Lập lịch kỹ thuật viên và phòng trị liệu để tối ưu công suất mà vẫn bảo đảm thời gian nghỉ.","Giám sát vệ sinh, khử khuẩn dụng cụ, đồ vải, bồn ngâm và quản lý hạn dùng sản phẩm.","Theo dõi doanh thu, RevPATH, tỷ lệ sử dụng phòng, doanh thu bán lẻ và tỷ lệ đặt lại.","Đào tạo kỹ năng, chứng chỉ chuyên môn và xử lý phản hồi, sự cố liên quan đến khách."],en:["Build the treatment menu, standard procedures for each service and health screening forms.","Schedule therapists and treatment rooms to optimize capacity while protecting rest breaks.","Supervise hygiene, disinfection of tools, linen and tubs and manage product expiry.","Track revenue, RevPATH, room utilization, retail sales and rebooking rates.","Train skills, maintain certifications and handle guest feedback and incidents."]},competencies:[{name:{vi:"Sàng lọc & an toàn khách",en:"Screening & guest safety"},desc:{vi:"Đọc phiếu tư vấn, nhận diện chống chỉ định như thai kỳ, huyết áp cao, bệnh da và chuyển hướng liệu trình phù hợp.",en:"Read consultation forms, spot contraindications such as pregnancy, high blood pressure or skin conditions and redirect to suitable treatments."}},{name:{vi:"Quản trị doanh thu spa",en:"Spa revenue management"},desc:{vi:"Dùng RevPATH, tỷ lệ sử dụng phòng và giá theo khung giờ để tối ưu doanh thu.",en:"Use RevPATH, room utilization and time-based pricing to optimize revenue."}},{name:{vi:"Vệ sinh & kiểm soát nhiễm khuẩn",en:"Hygiene & infection control"},desc:{vi:"Thiết lập quy trình làm sạch, khử khuẩn, đồ dùng một lần và kiểm tra định kỳ.",en:"Set cleaning, disinfection and single-use item procedures with regular checks."}},{name:{vi:"Quản lý đội ngũ kỹ thuật viên",en:"Therapist team management"},desc:{vi:"Phân công theo chứng chỉ, kèm cặp kỹ năng và bảo vệ sức khỏe nghề nghiệp của nhân viên.",en:"Assign by certification, coach skills and protect staff occupational health."}},{name:{vi:"Tư vấn & đạo đức nghề",en:"Advisory & professional ethics"},desc:{vi:"Tư vấn trung thực, không hứa hẹn tác dụng chữa bệnh, tôn trọng riêng tư và sự đồng ý của khách.",en:"Advise honestly, never promise medical cures and respect guest privacy and consent."}}],knowledge:{vi:["Phân biệt dịch vụ chăm sóc, thư giãn với khám bệnh, chữa bệnh: thủ thuật xâm lấn chỉ thực hiện tại cơ sở được cấp phép theo Luật Khám bệnh, chữa bệnh số 15/2023/QH15.","Các chống chỉ định phổ biến trong trị liệu: thai kỳ, sốt, huyết áp không kiểm soát, giãn tĩnh mạch, tổn thương da, sau phẫu thuật.","Chỉ số vận hành spa: RevPATH, tỷ lệ sử dụng phòng, tỷ lệ bán lẻ trên dịch vụ và tỷ lệ khách đặt lại.","Nguyên tắc vệ sinh, khử khuẩn dụng cụ dùng chung, đồ vải và nước bồn ngâm theo hướng dẫn của nhà sản xuất và cơ quan y tế.","Quy định hiện hành về bảo vệ dữ liệu cá nhân: thông tin sức khỏe của khách là dữ liệu nhạy cảm cần bảo mật."],en:["Distinguish care and relaxation services from medical treatment: invasive procedures belong only in facilities licensed under Medical Examination and Treatment Law No. 15/2023/QH15.","Common treatment contraindications: pregnancy, fever, uncontrolled blood pressure, varicose veins, broken skin and recent surgery.","Spa operating metrics: RevPATH, room utilization, retail-to-service ratio and rebooking rate.","Hygiene and disinfection of shared tools, linen and tub water following manufacturer and health authority guidance.","Current personal data protection rules: guest health information is sensitive data that must be kept confidential."]},tools:["Phần mềm quản lý spa và đặt lịch","Phiếu tư vấn & sàng lọc sức khỏe điện tử","Tủ tiệt trùng dụng cụ","Bảng theo dõi vệ sinh, khử khuẩn","Báo cáo doanh thu và công suất phòng","Hệ thống POS bán lẻ sản phẩm"],kpis:{vi:["RevPATH và tỷ lệ sử dụng phòng trị liệu theo tuần.","Tỷ lệ doanh thu bán lẻ trên doanh thu dịch vụ.","Tỷ lệ khách đặt lại và điểm hài lòng sau liệu trình.","Số sự cố an toàn khách và lỗi bỏ sót sàng lọc (mục tiêu bằng 0)."],en:["Weekly RevPATH and treatment room utilization.","Retail revenue as a share of service revenue.","Rebooking rate and post-treatment satisfaction score.","Guest safety incidents and missed screenings (target zero)."]},day:[{time:"08:30",vi:"Kiểm tra vệ sinh phòng trị liệu, nhiệt độ bồn ngâm, tủ tiệt trùng và hạn dùng sản phẩm.",en:"Check treatment room hygiene, tub temperatures, sterilizers and product expiry dates."},{time:"09:30",vi:"Rà lịch đặt trong ngày, đối chiếu phiếu sàng lọc và phân công kỹ thuật viên theo chứng chỉ.",en:"Review today's bookings, match screening forms and assign therapists by certification."},{time:"12:00",vi:"Tiếp khách VIP, tư vấn liệu trình và giải quyết yêu cầu thay đổi lịch.",en:"Welcome VIP guests, advise on treatments and handle rescheduling requests."},{time:"15:00",vi:"Phân tích RevPATH, công suất khung giờ thấp điểm và đề xuất chương trình ưu đãi.",en:"Analyze RevPATH and off-peak utilization and propose promotions."},{time:"19:00",vi:"Họp cuối ca về phản hồi khách, sự cố và kế hoạch đào tạo tuần tới.",en:"Hold the end-of-shift meeting on guest feedback, incidents and next week's training."}],mistakes:{vi:["Xác nhận lịch theo gói đã bán mà không đọc phiếu sàng lọc, bỏ sót chống chỉ định.","Tính RevPATH bằng doanh thu chia giờ đã bán, làm báo cáo công suất đẹp hơn thực tế.","Dùng giấy miễn trách nhiệm để biện minh cho liệu trình không an toàn."],en:["Confirming bookings from the sold package without reading the screening form, missing contraindications.","Computing RevPATH as revenue divided by sold hours, making capacity look better than it is.","Using a waiver to justify an unsafe treatment."]},career:[{vi:"Kỹ thuật viên trị liệu",en:"Spa therapist"},{vi:"Trưởng ca spa (Spa supervisor)",en:"Spa supervisor"},{vi:"Quản lý spa & chăm sóc sức khỏe",en:"Spa & wellness manager"},{vi:"Giám đốc spa và wellness cụm khu nghỉ dưỡng",en:"Cluster director of spa & wellness"}],glossary:[{term:"RevPATH",vi:"Doanh thu trên mỗi giờ trị liệu khả dụng, đo hiệu quả khai thác công suất spa.",en:"Revenue per available treatment hour, measuring how well spa capacity is monetized."},{term:"Contraindication",vi:"Chống chỉ định: tình trạng khiến một liệu trình có thể gây hại cho khách.",en:"A condition that makes a treatment potentially harmful to the guest."},{term:"Utilization",vi:"Tỷ lệ sử dụng: giờ đã bán chia cho giờ khả dụng của phòng hoặc kỹ thuật viên.",en:"Hours sold divided by available hours of rooms or therapists."},{term:"Retail ratio",vi:"Tỷ lệ doanh thu bán lẻ sản phẩm so với doanh thu dịch vụ trị liệu.",en:"Retail product revenue compared with treatment service revenue."},{term:"Consultation form",vi:"Phiếu tư vấn ghi tình trạng sức khỏe, dị ứng, thai kỳ và mong muốn của khách trước liệu trình.",en:"Pre-treatment form recording health conditions, allergies, pregnancy and guest preferences."}],quiz:[{q:{vi:"Spa có 5 phòng, mở 12 giờ/ngày trong 30 ngày, doanh thu trị liệu 540.000.000 VND. RevPATH là bao nhiêu?",en:"A spa has 5 rooms open 12 hours a day for 30 days with treatment revenue of 540,000,000 VND. What is RevPATH?"},options:{vi:["200.000 VND","250.000 VND","300.000 VND","450.000 VND"],en:["200,000 VND","250,000 VND","300,000 VND","450,000 VND"]},answer:2,explain:{vi:"Giờ khả dụng = 5 x 12 x 30 = 1.800; RevPATH = 540.000.000 / 1.800 = 300.000 VND.",en:"Available hours = 5 x 12 x 30 = 1,800; RevPATH = 540,000,000 / 1,800 = 300,000 VND."}},{q:{vi:"Khách mang thai muốn dùng liệu trình xông hơi nhiệt cao. Bạn xử lý thế nào?",en:"A pregnant guest wants a high-heat sauna treatment. How do you respond?"},options:{vi:["Từ chối tế nhị và đề xuất liệu trình an toàn cho thai kỳ","Đồng ý nếu khách ký cam kết","Giảm thời gian xông còn một nửa","Để khách tự quyết"],en:["Decline tactfully and offer a pregnancy-safe treatment","Agree if the guest signs a waiver","Halve the sauna time","Let the guest decide alone"]},answer:0,explain:{vi:"Nhiệt cao là chống chỉ định trong thai kỳ; an toàn của khách quan trọng hơn doanh thu và giấy cam kết.",en:"High heat is contraindicated in pregnancy; guest safety outweighs revenue and waivers."}},{q:{vi:"Tỷ lệ sử dụng phòng trị liệu được tính như thế nào?",en:"How is treatment room utilization calculated?"},options:{vi:["Doanh thu chia số khách","Số kỹ thuật viên chia số phòng","Giờ khả dụng chia giờ đã bán","Giờ đã bán chia giờ khả dụng"],en:["Revenue divided by guests","Therapists divided by rooms","Available hours divided by sold hours","Sold hours divided by available hours"]},answer:3,explain:{vi:"Tỷ lệ sử dụng = giờ đã bán / giờ khả dụng, cho biết công suất được khai thác bao nhiêu phần trăm.",en:"Utilization = sold hours / available hours, showing the share of capacity in use."}},{q:{vi:"Spa không có giấy phép khám chữa bệnh được phép làm dịch vụ nào?",en:"Which service may a spa without a medical license offer?"},options:{vi:["Tiêm chất làm đầy","Massage thư giãn và chăm sóc da không xâm lấn","Phẫu thuật thẩm mỹ mí mắt","Kê đơn thuốc điều trị mụn"],en:["Dermal filler injections","Relaxation massage and non-invasive skin care","Eyelid cosmetic surgery","Prescribing acne medication"]},answer:1,explain:{vi:"Thủ thuật xâm lấn và kê đơn thuộc hoạt động khám chữa bệnh, chỉ cơ sở được cấp phép mới thực hiện.",en:"Invasive procedures and prescribing are medical activities reserved for licensed facilities."}}]}}}),n.JobLabContentClusters=(n.JobLabContentClusters||[]).concat(10)})(window.KKR);
